    /// x0x #380: outbound demand metering — a locally-originated publish
    /// must move the per-kind / per-topic wire counters AND the origin split
    /// (`local`), and the snapshot must serialise (x0x /diagnostics/gossip
    /// passes it through automatically).
    #[tokio::test]
    async fn outbound_metering_counts_local_publish_and_serialises() {
        let peer_id = test_peer_id(1);
        let eager = test_peer_id(2);
        let transport = RecordingTransport::new(peer_id);
        let pubsub =
            PlumtreePubSub::new_with_task_control(peer_id, transport, test_signing_key(), false);
        let topic = TopicId::new([21u8; 32]);
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics.entry(topic).or_insert_with(TopicState::new);
            state.eager_peers.insert(eager);
        }

        pubsub
            .publish_local(topic, Bytes::from_static(b"meter-me"))
            .await
            .expect("publish succeeds against the recording transport");

        let snapshot = pubsub.stage_stats();
        let eager_meter = snapshot
            .outbound_by_kind
            .get("eager")
            .expect("eager kind meter present");
        assert!(
            eager_meter.msgs >= 1 && eager_meter.bytes > 0,
            "local publish must count eager wire sends, got {eager_meter:?}"
        );
        let topic_meter = snapshot
            .outbound_by_topic
            .get(&topic.to_string())
            .expect("per-topic meter present for the published topic");
        assert!(
            topic_meter.eager.msgs >= 1 && topic_meter.eager.bytes > 0,
            "per-topic eager meter must move, got {topic_meter:?}"
        );
        assert_eq!(
            snapshot.outbound_publish_origin.local_msgs, 1,
            "one locally-originated publish"
        );
        assert!(
            snapshot.outbound_publish_origin.local_bytes > 0,
            "local origin bytes counted"
        );
        assert_eq!(
            snapshot.outbound_publish_origin.relay_msgs, 0,
            "nothing relayed in this fixture"
        );

        // The snapshot must serialise — x0x's /diagnostics/gossip passes
        // PubSubStageStatsSnapshot straight through to JSON.
        let json = serde_json::to_value(&snapshot).expect("snapshot serialises");
        assert!(
            json.get("outbound_by_topic").is_some()
                && json.get("outbound_by_kind").is_some()
                && json.get("outbound_publish_origin").is_some(),
            "metering fields present in serialised snapshot"
        );
    }

    /// x0x #380: forwarding another node's message must land in the RELAY
    /// half of the origin split — the rate-cap decision hinges on telling
    /// local demand apart from amplified relay traffic (an idle daemon
    /// sending ~104 EAGER/s is relay, not local publishes).
    #[tokio::test]
    async fn outbound_metering_counts_relay_forward() {
        let peer_id = test_peer_id(1);
        let from_peer = test_peer_id(2);
        let eager = test_peer_id(3);
        let transport = RecordingTransport::new(peer_id);
        let pubsub =
            PlumtreePubSub::new_with_task_control(peer_id, transport, test_signing_key(), false);
        let topic = TopicId::new([22u8; 32]);
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics.entry(topic).or_insert_with(TopicState::new);
            // `from_peer` sent the message; `eager` is the forward target.
            state.eager_peers.insert(from_peer);
            state.eager_peers.insert(eager);
        }

        let sender_key = test_signing_key();
        let payload = Bytes::from_static(b"relayed-payload");
        let eager_msg = signed_eager_message(&sender_key, topic, [77u8; 32], payload);
        let bytes: Bytes = postcard::to_stdvec(&eager_msg)
            .expect("eager message serialises")
            .into();
        pubsub
            .handle_message(from_peer, bytes)
            .await
            .expect("inbound eager handled");

        let snapshot = pubsub.stage_stats();
        assert_eq!(
            snapshot.outbound_publish_origin.relay_msgs, 1,
            "forwarding another node's message is relay traffic"
        );
        assert!(
            snapshot.outbound_publish_origin.relay_bytes > 0,
            "relay bytes counted"
        );
        assert_eq!(
            snapshot.outbound_publish_origin.local_msgs, 0,
            "no local publish in this fixture"
        );
        let eager_meter = snapshot
            .outbound_by_kind
            .get("eager")
            .expect("eager kind meter present");
        assert!(
            eager_meter.msgs >= 1,
            "the forward fan-out counts as eager wire sends"
        );
    }

    #[tokio::test]
    async fn test_stage_stats_record_message_kinds_and_tree_ops() {
        let peer_id = test_peer_id(1);
        let from_peer = test_peer_id(2);
        let (transport, _started_rx) = BlockingTransport::new(peer_id);
        transport.release_sends(8);
        let sender_key = test_signing_key();
        let pubsub = PlumtreePubSub::new_with_task_control(
            peer_id,
            Arc::clone(&transport),
            test_signing_key(),
            false,
        );
        let topic = TopicId::new([8u8; 32]);
        let msg_id = [9u8; 32];
        let eager = signed_eager_message(
            &sender_key,
            topic,
            msg_id,
            Bytes::from_static(b"kind-counter-payload"),
        );
        let eager_bytes: Bytes = postcard::to_stdvec(&eager)
            .expect("eager message serializes")
            .into();

        pubsub
            .handle_message(from_peer, eager_bytes.clone())
            .await
            .expect("first eager handled");
        pubsub
            .handle_message(from_peer, eager_bytes)
            .await
            .expect("duplicate eager prunes sender");

        let iwant_payload: Bytes = postcard::to_stdvec(&vec![msg_id])
            .expect("iwant payload serializes")
            .into();
        let iwant = signed_control_message(
            &sender_key,
            topic,
            msg_id,
            MessageKind::IWant,
            iwant_payload,
        );
        pubsub
            .handle_message(
                from_peer,
                postcard::to_stdvec(&iwant)
                    .expect("iwant message serializes")
                    .into(),
            )
            .await
            .expect("iwant grafts sender");

        let missing_id = [7u8; 32];
        let ihave_payload: Bytes = postcard::to_stdvec(&vec![missing_id])
            .expect("ihave payload serializes")
            .into();
        let ihave = signed_control_message(
            &sender_key,
            topic,
            missing_id,
            MessageKind::IHave,
            ihave_payload,
        );
        pubsub
            .handle_message(
                from_peer,
                postcard::to_stdvec(&ihave)
                    .expect("ihave message serializes")
                    .into(),
            )
            .await
            .expect("ihave handled");

        let ae_payload: Bytes =
            postcard::to_stdvec(&AntiEntropyPayload::Digest { msg_ids: vec![] })
                .expect("anti-entropy payload serializes")
                .into();
        let anti_entropy = signed_control_message(
            &sender_key,
            topic,
            [0u8; 32],
            MessageKind::AntiEntropy,
            ae_payload,
        );
        pubsub
            .handle_message(
                from_peer,
                postcard::to_stdvec(&anti_entropy)
                    .expect("anti-entropy message serializes")
                    .into(),
            )
            .await
            .expect("anti-entropy handled");

        let stats = pubsub.stage_stats().message_kinds;
        assert_eq!(stats.eager, 2);
        assert_eq!(stats.ihave, 1);
        assert_eq!(stats.iwant, 1);
        assert_eq!(stats.anti_entropy, 1);
        assert_eq!(stats.prune, 1);
        assert_eq!(stats.graft, 2);
        assert_eq!(stats.decode_failed, 0);
    }

    /// x0x #674 (Design B): the bounded msg-id cache is the verify memo.
    /// A duplicate EAGER — including an IWANT repair response, which
    /// returns as an EAGER frame carrying the original msg_id — must be
    /// dropped by the dedup check BEFORE the ML-DSA-65 verify. The first
    /// arrival verifies exactly once; the second arrival never reaches
    /// `verify_message_signature`, still counts as inbound EAGER, delivers
    /// to subscribers exactly once, and still runs the duplicate-EAGER
    /// PRUNE against its sender.
    #[tokio::test(start_paused = true)]
    async fn duplicate_eager_is_dropped_before_verify() {
        let peer_id = test_peer_id(1);
        let first_peer = test_peer_id(2);
        let dup_peer = test_peer_id(3);
        let transport = RecordingTransport::new(peer_id);
        let sender_key = test_signing_key();
        let pubsub = PlumtreePubSub::new_with_task_control(
            peer_id,
            Arc::clone(&transport),
            test_signing_key(),
            false,
        );
        let topic = TopicId::new([31u8; 32]);
        let mut rx = pubsub.subscribe_ready(topic).await;
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics.entry(topic).or_insert_with(TopicState::new);
            state.eager_peers.insert(first_peer);
            state.eager_peers.insert(dup_peer);
        }

        let payload = Bytes::from_static(b"dedup-before-verify");
        let msg = signed_eager_message(&sender_key, topic, [44u8; 32], payload.clone());
        let bytes: Bytes = postcard::to_stdvec(&msg)
            .expect("eager message serializes")
            .into();

        pubsub
            .handle_message(first_peer, bytes.clone())
            .await
            .expect("first eager admitted");
        let first = pubsub.stage_stats();
        assert_eq!(first.verify.count, 1, "the first arrival pays the verify");
        assert_eq!(
            first.eager_duplicate_dropped_pre_verify, 0,
            "a novel msg_id is not a duplicate"
        );

        pubsub
            .handle_message(dup_peer, bytes)
            .await
            .expect("duplicate eager dropped");
        let second = pubsub.stage_stats();
        assert_eq!(
            second.verify.count, 1,
            "the duplicate is dropped by the msg-id cache without any verify"
        );
        assert_eq!(
            second.eager_duplicate_dropped_pre_verify, 1,
            "the duplicate is counted where it is dropped"
        );
        assert_eq!(
            second.message_kinds.eager, 2,
            "both arrivals still count as inbound EAGER"
        );

        // Exactly one subscriber delivery — from the first, verified copy.
        let (delivered_from, delivered_payload) = rx
            .try_recv()
            .expect("the first copy is delivered to the subscriber");
        assert_eq!(delivered_from, first_peer);
        assert_eq!(delivered_payload, payload);
        assert!(
            rx.try_recv().is_err(),
            "the duplicate must not be re-delivered"
        );

        // Existing duplicate-EAGER handling is preserved: the duplicate
        // sender is PRUNED to lazy; the first sender stays eager.
        {
            let topics = pubsub.topics.read_topic(&topic).await;
            let state = topics.get(&topic).expect("topic state exists");
            assert!(
                state.eager_peers.contains(&first_peer),
                "the first sender stays eager"
            );
            assert!(
                !state.eager_peers.contains(&dup_peer),
                "the duplicate sender is pruned from eager"
            );
            assert!(
                state.lazy_peers.contains(&dup_peer),
                "the duplicate sender is demoted to lazy"
            );
        }
    }

    /// x0x #674 safety: an UNVERIFIED duplicate EAGER — a forged frame
    /// claiming a msg_id already in the cache — can only penalise its own
    /// transport-authenticated sender. It must never prune a different
    /// legitimate eager peer: the legitimate peer delivered the genuine
    /// first copy and stays eager, while the forger is demoted to lazy
    /// and its frame is never verified.
    #[tokio::test(start_paused = true)]
    async fn forged_duplicate_eager_prunes_only_its_sender() {
        let peer_id = test_peer_id(1);
        let legit_peer = test_peer_id(2);
        let attacker = test_peer_id(3);
        let transport = RecordingTransport::new(peer_id);
        let sender_key = test_signing_key();
        let pubsub = PlumtreePubSub::new_with_task_control(
            peer_id,
            Arc::clone(&transport),
            test_signing_key(),
            false,
        );
        let topic = TopicId::new([32u8; 32]);
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics.entry(topic).or_insert_with(TopicState::new);
            state.eager_peers.insert(legit_peer);
            state.eager_peers.insert(attacker);
        }

        // The genuine first copy from the legitimate eager peer.
        let payload = Bytes::from_static(b"genuine-first-copy");
        let msg = signed_eager_message(&sender_key, topic, [45u8; 32], payload);
        let bytes: Bytes = postcard::to_stdvec(&msg)
            .expect("eager message serializes")
            .into();
        pubsub
            .handle_message(legit_peer, bytes)
            .await
            .expect("genuine first copy admitted");
        assert_eq!(pubsub.stage_stats().verify.count, 1);

        // The forged duplicate: same msg_id, corrupted publisher
        // signature — the frame cannot authenticate. If the dedup check
        // ran after the verify this would be an Err (invalid signature);
        // dropped pre-verify it is an Ok duplicate-drop that demotes only
        // the sender.
        let mut forged = msg;
        forged.signature[0] ^= 1;
        let forged_bytes: Bytes = postcard::to_stdvec(&forged)
            .expect("forged eager serializes")
            .into();
        pubsub
            .handle_message(attacker, forged_bytes)
            .await
            .expect("forged duplicate dropped as a duplicate, not an error");

        let stats = pubsub.stage_stats();
        assert_eq!(
            stats.verify.count, 1,
            "the forged frame never reaches the verify"
        );
        assert_eq!(stats.eager_duplicate_dropped_pre_verify, 1);

        {
            let topics = pubsub.topics.read_topic(&topic).await;
            let state = topics.get(&topic).expect("topic state exists");
            assert!(
                state.eager_peers.contains(&legit_peer),
                "an unverified duplicate cannot prune a legitimate eager peer"
            );
            assert!(
                !state.eager_peers.contains(&attacker),
                "the forger itself is demoted from eager"
            );
            assert!(
                state.lazy_peers.contains(&attacker),
                "the forger is demoted to lazy"
            );
        }
    }

    /// Issue #58: the pre-verify dedupe fast path must not take the
    /// per-topic shard WRITE lock for its read-only cache lookup. On a
    /// bootstrap ~72% of inbound EAGER frames are cache MISSES, and paying
    /// a write acquisition for every one of them serialized all workers on
    /// the hot path — `dedupe_lock_acquire` measured 4.12 s of wait per
    /// wall second on an x0x bootstrap node (x0x #656). This test drives a
    /// realistic miss/duplicate mix through `handle_eager` on an empty-mesh
    /// topic (no send-claim acquisitions) and pins the acquisition profile:
    /// every frame takes exactly ONE read probe, and the write lock is
    /// taken only where mutation is actually required — the duplicate
    /// upgrade and the novel post-verify dedupe/cache insert. On the
    /// pre-#58 code the same mix takes a fast-path write acquisition per
    /// frame as well (write count 2N+D vs N+D here).
    #[tokio::test]
    async fn dedupe_miss_path_takes_no_fast_path_write_lock() {
        let peer_id = test_peer_id(1);
        let transport = RecordingTransport::new(peer_id);
        let sender_key = test_signing_key();
        let pubsub = PlumtreePubSub::new_with_task_control(
            peer_id,
            Arc::clone(&transport),
            test_signing_key(),
            false,
        );
        let topic = TopicId::new([58u8; 32]);

        // 92 novel frames, then 36 duplicates of already-cached ids — a
        // true 72%/28% miss/duplicate split over 128 frames (the issue's
        // measured fleet ratio; the round-1 draft used 100/28, which is
        // actually 78/22).
        const NOVEL: usize = 92;
        const DUPLICATES: usize = 36;
        let mut messages = Vec::with_capacity(NOVEL);
        for i in 0..NOVEL {
            let msg_id = [58u8; 31]
                .iter()
                .copied()
                .chain(std::iter::once(i as u8))
                .collect::<Vec<u8>>()
                .try_into()
                .expect("msg id is 32 bytes");
            messages.push(signed_eager_message(
                &sender_key,
                topic,
                msg_id,
                Bytes::from(vec![i as u8; 16]),
            ));
        }
        for msg in &messages {
            pubsub
                .handle_eager(test_peer_id(2), topic, msg.clone())
                .await
                .expect("novel frame admitted");
        }
        for msg in messages.iter().take(DUPLICATES) {
            pubsub
                .handle_eager(test_peer_id(3), topic, msg.clone())
                .await
                .expect("duplicate frame dropped as duplicate, not an error");
        }

        let stats = pubsub.stage_stats();
        // Every fast-path frame — novel or duplicate — probes exactly once
        // under a READ lock.
        assert_eq!(
            stats.dedupe_lock_acquire_read.count,
            (NOVEL + DUPLICATES) as u64,
            "one read probe per inbound frame (issue #58)"
        );
        // Write acquisitions: NOVEL post-verify dedupe/cache inserts +
        // DUPLICATES probe-hit upgrades. The NOVEL misses take NO
        // fast-path write acquisition — that is the fix. The pre-#58
        // profile on this exact mix is 2*NOVEL + DUPLICATES = 220 write
        // acquisitions (verified on an origin/main transplant), i.e. this
        // is a 41.8% cut with zero fast-path write acquisitions on the
        // miss path.
        assert_eq!(
            stats.dedupe_lock_acquire.count,
            (NOVEL + DUPLICATES) as u64,
            "write lock only for duplicate upgrades and post-verify inserts — the pre-#58 profile on this mix was 2*NOVEL + DUPLICATES = 220"
        );
        // Semantics preserved: every novel frame verified exactly once,
        // every duplicate dropped pre-verify, none admitted twice, none
        // dropped.
        assert_eq!(stats.verify.count, NOVEL as u64);
        assert_eq!(stats.eager_duplicate_dropped_pre_verify, DUPLICATES as u64);
        {
            let topics = pubsub.topics.read_topic(&topic).await;
            let state = topics.get(&topic).expect("topic state exists");
            assert_eq!(
                state.message_cache.len(),
                NOVEL,
                "exactly the novel ids are cached — no duplicate insert, no loss (usize)"
            );
        }
    }

    /// Issue #58 race guard: many tasks concurrently deliver frames
    /// carrying the SAME unseen msg_id. The read-probe fast path must still
    /// admit the message exactly once — concurrent probes all miss, the
    /// losers each run the lockless ML-DSA-65 verify step (no topic lock is
    /// held across `verify_message_signature` — see the comment at the call
    /// site in `handle_eager_admitted`), then the post-verify double-check
    /// under the write lock drops every racer that arrived while the winner
    /// was between probe and insert. Exactly one subscriber delivery,
    /// exactly one cache entry, no deadlock.
    ///
    /// Round 2: each racer carries a DISTINCT payload under the same
    /// msg_id (legal — msg_id is read from the header and never
    /// recomputed), and every frame is pre-signed BEFORE the spawn loop so
    /// signing cost cannot serialize the racers. Distinct payloads keep
    /// this test load-bearing: with identical payloads the independent
    /// payload-hash replay layer would suppress the losers regardless of
    /// the msg_id check, so breaking the post-verify double-check left the
    /// round-1 version passing. With distinct payloads, breaking that
    /// re-check fails this test (verified by mutation).
    ///
    /// Round 3 (fixes #68): `verify.count >= 1` replaces `>= 2`.
    ///
    /// Why not `>= 2`: independent testing showed that under ~9x CPU
    /// oversubscription `verify.count` collapsed to 1 in 6 of 120 runs — a
    /// 5% spurious failure rate. Unloaded it was 100/100 green, so the
    /// failure is load-induced and would have appeared only in CI. The floor
    /// of `>= 2` was the scheduler's natural overlap (deterministically
    /// `worker_threads` in stable conditions), so any threshold above 1 may
    /// spuriously fail under load. Additionally, `>= 2` had ~2.5%
    /// mutation-detection power against the "signing moved into task" mutation
    /// that the round-2 review was designed to catch.
    ///
    /// Why `== RACERS` is unachievable: `verify.count` saturates at
    /// `worker_threads` regardless of gates or barriers. Since `verify` runs
    /// without a topic lock (~1 ms of pure CPU), the first insertion lands
    /// before the queued `RACERS - worker_threads` tasks even start; they
    /// see a read-probe HIT and never verify. This means any reduction of
    /// RACERS down to `worker_threads + 1` or more is completely invisible
    /// to `verify.count` — a drop from 32 to 9 racers would not move the
    /// counter at all. A structural `== RACERS` assertion was tried in four
    /// configurations (gate alone, gate + yield_now, gate + Barrier(33),
    /// gate + Barrier(33) + worker_threads=32) and failed consistently
    /// (verify.count in the range 8–22, never 32) across 80 runs.
    ///
    /// Why `>= 1` is the correct floor: the winner always runs the
    /// ML-DSA-65 verify (`verify_message_signature`) before inserting into
    /// the cache. A value of 0 would mean no frame was admitted via the
    /// verify path — which would indicate either the topic is mistakenly
    /// registered (bypassing the pre-verify dedup block) or the fast-path
    /// dedup is returning a spurious HIT on a fresh msg_id. Neither can
    /// happen with correct code, so `>= 1` is an infallible lower bound
    /// that never produces a spurious failure under any CPU load.
    ///
    /// What pins the actual concurrent overlap: the existing assertions
    /// already do this structurally. `dedupe_lock_acquire_read.count == RACERS`
    /// proves all 32 frames took the read-probe path (none short-circuited
    /// before the lock). The distinct-payload setup ensures the post-verify
    /// double-check is the real guard (breaking it was verified to fail the
    /// test in round 2). The single-delivery subscriber assertion proves
    /// exactly one racer won. Together these assertions leave no room for the
    /// overlap to have been absent — they just don't require an exact
    /// `verify.count` number, which would be scheduler-dependent.
    #[tokio::test(flavor = "multi_thread", worker_threads = 8)]
    async fn concurrent_same_msg_id_frames_admit_exactly_once() {
        let peer_id = test_peer_id(1);
        let transport = RecordingTransport::new(peer_id);
        let sender_key = test_signing_key();
        let pubsub = Arc::new(PlumtreePubSub::new_with_task_control(
            peer_id,
            Arc::clone(&transport),
            test_signing_key(),
            false,
        ));
        let topic = TopicId::new([59u8; 32]);
        let mut subscriber = pubsub.subscribe_ready(topic).await;

        const RACERS: usize = 32;
        let msg_id = [59u8; 32];
        let mut frames = Vec::with_capacity(RACERS);
        for i in 0..RACERS {
            frames.push(signed_eager_message(
                &sender_key,
                topic,
                msg_id,
                Bytes::from(format!("race-{i}")),
            ));
        }
        let frames = Arc::new(frames);
        let mut tasks = tokio::task::JoinSet::new();
        for i in 0..RACERS {
            let pubsub = Arc::clone(&pubsub);
            let frames = Arc::clone(&frames);
            tasks.spawn(async move {
                pubsub
                    .handle_eager(test_peer_id(4 + i as u8), topic, frames[i].clone())
                    .await
                    .expect("every racer completes without error");
            });
        }
        // Deadlock guard: the whole hammer must settle well inside a
        // generous bound even under contention.
        let joined = tokio::time::timeout(Duration::from_secs(30), tasks.join_all()).await;
        assert!(
            joined.is_ok(),
            "concurrent same-msg_id hammer must not deadlock"
        );

        // Exactly one admission: one subscriber delivery...
        let delivered = subscriber.try_recv();
        assert!(
            delivered.is_ok(),
            "the winning racer must deliver to the subscriber exactly once"
        );
        assert!(
            subscriber.try_recv().is_err(),
            "no second admission may deliver again"
        );
        // ...one cache entry...
        {
            let topics = pubsub.topics.read_topic(&topic).await;
            let state = topics.get(&topic).expect("topic state exists");
            assert_eq!(state.message_cache.len(), 1);
            assert!(state.has_message(&[59u8; 32]));
        }
        // ...and every frame probed the cache exactly once under a read
        // lock.
        let stats = pubsub.stage_stats();
        assert_eq!(
            stats.dedupe_lock_acquire_read.count, RACERS as u64,
            "every racing frame takes exactly one read probe"
        );
        // The winner always runs verify_message_signature before inserting.
        // A count of 0 would mean the winning frame skipped verify entirely,
        // which would indicate a broken fast path (spurious pre-verify HIT on
        // a fresh msg_id) or accidental topic registration. Neither happens
        // with correct code, so >= 1 is always true. The exact count is
        // scheduler-dependent (deterministically worker_threads under normal
        // load) and is not asserted here — the real overlap guarantee comes
        // from dedupe_lock_acquire_read.count == RACERS above plus the
        // single-delivery assertion above. (Refs #58, #67, #68.)
        assert!(
            stats.verify.count >= 1,
            "verify.count=0: no racer ran the ML-DSA-65 verify path — the \
             winning frame either hit the pre-verify dedup cache on a fresh \
             msg_id (spurious HIT) or the topic is incorrectly registered"
        );
    }

    #[tokio::test]
    async fn test_stage_stats_record_pubsub_decode_failures() {
        let peer_id = test_peer_id(1);
        let (transport, _started_rx) = BlockingTransport::new(peer_id);
        let pubsub =
            PlumtreePubSub::new_with_task_control(peer_id, transport, test_signing_key(), false);

        let err = pubsub
            .handle_message(test_peer_id(2), Bytes::from_static(b"not-postcard"))
            .await;
        assert!(err.is_err());
        assert_eq!(pubsub.stage_stats().message_kinds.decode_failed, 1);
    }

    #[tokio::test]
    async fn test_publish_and_subscribe() {
        let peer_id = test_peer_id(1);
        let transport = test_transport().await;
        let signing_key = test_signing_key();
        let pubsub = PlumtreePubSub::new(peer_id, transport, signing_key);
        let topic = TopicId::new([1u8; 32]);

        let mut rx = pubsub.subscribe(topic);
        tokio::time::sleep(tokio::time::Duration::from_millis(10)).await;

        let data = Bytes::from("test message");
        pubsub.publish(topic, data.clone()).await.ok();

        let received =
            tokio::time::timeout(tokio::time::Duration::from_millis(100), rx.recv()).await;

        assert!(received.is_ok());
        let (_, payload) = received.unwrap().unwrap();
        assert_eq!(payload, data);
    }

    #[tokio::test]
    async fn test_zero_fanout_publish_is_counted_and_returned() {
        let peer_id = test_peer_id(1);
        let transport = test_transport().await;
        let pubsub = PlumtreePubSub::new(peer_id, transport, test_signing_key());
        let topic = TopicId::new([0x32; 32]);

        let counts = pubsub
            .publish_local_with_fanout(topic, Bytes::from_static(b"zero-fanout"))
            .await
            .expect("zero-fanout publish preserves Ok semantics");

        assert_eq!(counts.attempted, 0);
        assert_eq!(counts.succeeded, 0);
        let stats = pubsub.stage_stats();
        assert_eq!(stats.zero_fanout_publishes, 1);
        assert_eq!(
            stats.zero_fanout_publishes_by_topic.get(&topic.to_string()),
            Some(&1)
        );
    }

    // ---- 504: FanoutCounts stage accounting keeps an empty eager set,
    // full byte deferral, admission drops, and claim skips distinct ----

    #[tokio::test]
    async fn fanout_stage_counts_empty_eager_set_is_all_zero() {
        let peer_id = test_peer_id(1);
        let transport = RecordingTransport::new(peer_id);
        let pubsub = PlumtreePubSub::new_with_task_control(
            peer_id,
            Arc::clone(&transport),
            test_signing_key(),
            false,
        );
        let topic = TopicId::new([0x61; 32]);

        let counts = pubsub
            .publish_local_with_fanout(topic, Bytes::from_static(b"no-peers"))
            .await
            .expect("publish returns Ok");

        assert_eq!(
            counts,
            FanoutCounts::default(),
            "empty membership must be distinguishable from any exclusion"
        );
        assert_eq!(counts.candidates, 0);
        assert_eq!(pubsub.stage_stats().zero_fanout_publishes, 1);
    }

    #[tokio::test]
    async fn fanout_stage_counts_full_byte_deferral_is_not_empty_membership() {
        // The 504 field failure: two eager candidates, both byte-deferred
        // before any claim. attempted == 0 alone reads as "no peers"; the
        // stage counts must say candidates == 2, byte_rejected == 2.
        //
        // This drives the *forwarded* dispatcher fan-out. It originally drove
        // `publish_local_with_fanout`, but the opt-in policy added on top of
        // this stack protects local-origin publishes from byte shedding
        // outright, so that scenario can no longer produce a deferral — see
        // `shed_normal_never_drops_critical_or_local_origin_over_budget`,
        // which asserts exactly that. The subject here is the stage
        // accounting, which is unchanged on the path where shedding is legal.
        let peer_id = test_peer_id(1);
        let transport = RecordingTransport::new(peer_id);
        let pubsub = PlumtreePubSub::new_with_task_control(
            peer_id,
            Arc::clone(&transport),
            test_signing_key(),
            false,
        );
        let topic = TopicId::new([0x62; 32]);
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics.entry(topic).or_insert_with(TopicState::new);
            state.eager_peers.insert(test_peer_id(2));
            state.eager_peers.insert(test_peer_id(3));
        }
        // Drain most of a valid bucket first. The publish frame remains below
        // the configured maximum, but neither candidate can leave the fixed
        // recovery reserve behind, so both data reservations defer.
        assert!(pubsub.configure_leaf_egress(Some(LeafEgressConfig {
            soft_bytes_per_second: 0,
            hard_bytes_per_second: 1,
            burst_bytes: 8192,
            max_serialized_frame_bytes: 8192,
            policy: BytePolicy::ShedNormal,
        })));
        let _drain = pubsub
            .egress_limiter
            .try_reserve_data(
                egress::RecoveryIntentKey {
                    peer: [0x91; 32],
                    scope: [0x91; 32],
                    family: [0x92; 32],
                    operation: [0x93; 32],
                },
                6144,
                false,
            )
            .expect("valid setup reservation drains initial tokens");

        let counts = pubsub
            .parallel_send_to_peers(
                topic,
                vec![test_peer_id(2), test_peer_id(3)],
                GossipStreamType::PubSub,
                Bytes::from_static(b"attempt4"),
                "EAGER",
                true,
            )
            .await
            .1;

        assert_eq!(counts.candidates, 2);
        assert_eq!(counts.byte_rejected, 2);
        assert_eq!(counts.admission_dropped, 0);
        assert_eq!(counts.claim_skipped, 0);
        assert_eq!(counts.attempted, 0);
        assert_eq!(counts.succeeded, 0);
        assert_eq!(
            counts.candidates,
            counts.byte_rejected
                + counts.admission_dropped
                + counts.claim_skipped
                + counts.attempted
        );
        assert!(transport.sent_frames().is_empty());
    }

    /// #504 opt-in policy harness: a topic with one eager peer, a configured
    /// Leaf byte budget, and the data bucket already drained past its hard
    /// threshold. Every test below starts over budget, so the only variable
    /// left is whether policy permits the send to be shed.
    async fn over_budget_pubsub(
        priority: TopicPriority,
        policy: BytePolicy,
    ) -> (
        Arc<PlumtreePubSub<RecordingTransport>>,
        Arc<RecordingTransport>,
        TopicId,
        PeerId,
    ) {
        let peer_id = test_peer_id(1);
        let target = test_peer_id(2);
        let transport = RecordingTransport::new(peer_id);
        let pubsub = Arc::new(PlumtreePubSub::new_with_task_control(
            peer_id,
            Arc::clone(&transport),
            test_signing_key(),
            false,
        ));
        let topic = TopicId::new([0x5b; 32]);
        pubsub.admission.registry().register(topic, priority);
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            topics
                .entry(topic)
                .or_insert_with(TopicState::new)
                .eager_peers
                .insert(target);
        }
        store_connected_peers_snapshot(
            pubsub.connected_peers_snapshot.as_ref(),
            Some(HashSet::from([target])),
        );
        assert!(pubsub.configure_leaf_egress(Some(LeafEgressConfig {
            soft_bytes_per_second: 0,
            hard_bytes_per_second: 128 * 1024,
            burst_bytes: 4 * 1024 * 1024,
            max_serialized_frame_bytes: 4 * 1024 * 1024,
            policy,
        })));
        // Spend the data allowance down to the recovery reserve, so any
        // further data frame is over the hard threshold.
        assert!(
            pubsub
                .egress_limiter
                .try_reserve_data(
                    egress::RecoveryIntentKey {
                        peer: [0x91; 32],
                        scope: [0x91; 32],
                        family: [0x92; 32],
                        operation: [0x93; 32],
                    },
                    3 * 1024 * 1024,
                    false,
                )
                .is_ok(),
            "setup must drain the data allowance"
        );
        (pubsub, transport, topic, target)
    }

    async fn fanout_over_budget(
        pubsub: &PlumtreePubSub<RecordingTransport>,
        topic: TopicId,
        target: PeerId,
        forwarded: bool,
    ) -> FanoutCounts {
        pubsub
            .parallel_send_to_peers(
                topic,
                vec![target],
                GossipStreamType::PubSub,
                Bytes::from(vec![0x7a_u8; 64 * 1024]),
                "EAGER",
                forwarded,
            )
            .await
            .1
    }

    /// The forwarded fan-out detaches accounting, so its send completes in a
    /// spawned task and `succeeded` is not meaningful there. Delivery is
    /// observed on the transport instead.
    async fn wait_for_sent_frames(transport: &RecordingTransport, expected: usize) -> usize {
        for _ in 0..200 {
            let sent = transport.sent_frames().len();
            if sent >= expected {
                return sent;
            }
            tokio::time::sleep(Duration::from_millis(5)).await;
        }
        transport.sent_frames().len()
    }

    /// WHY: a byte budget is an observation instrument until an operator says
    /// otherwise. The archived #504 stack enforced whenever
    /// `hard_bytes_per_second != 0`, which meant that merely *measuring*
    /// egress silently started dropping gossip. If that implicit rule comes
    /// back, this fan-out is over budget and `byte_rejected` becomes 1.
    #[tokio::test]
    async fn observe_only_sheds_nothing_past_the_hard_threshold() {
        let (pubsub, transport, topic, target) =
            over_budget_pubsub(TopicPriority::Normal, BytePolicy::ObserveOnly).await;
        assert!(
            pubsub.egress_limiter.enabled(),
            "the budget must be accounting — this test is about policy, not about being off"
        );
        assert!(!pubsub.egress_limiter.enforcing());

        let counts = fanout_over_budget(&pubsub, topic, target, true).await;

        assert_eq!(
            counts.byte_rejected, 0,
            "ObserveOnly must never deny a send, however far over budget"
        );
        // Admission is not delivery. A protected peer admitted without a
        // reservation is rejected by the transport fence and booked as a
        // timeout, so the frame never reaches the wire — ObserveOnly would
        // shed 100% of egress one stage later. Assert the frame was actually
        // sent and that the fence recorded no violation.
        assert_eq!(
            counts.attempted, 1,
            "the protected peer must reach the transport, not be dropped at the fence"
        );
        assert_eq!(
            wait_for_sent_frames(&transport, 1).await,
            1,
            "the protected frame must reach the wire"
        );
        assert_eq!(transport.sent_frames()[0].0, target);
        let snapshot = pubsub.leaf_egress_snapshot();
        assert_eq!(
            snapshot.invariant_violations, 0,
            "a protected send must carry a real reservation, not trip the fence"
        );
        assert!(
            snapshot.charged_bytes >= 64 * 1024,
            "a protected send is charged, so charged_bytes stays honest"
        );
        assert!(
            snapshot.shed_suppressed >= 1,
            "the overrun must still be metered — an unobservable ObserveOnly \
             budget would tell an operator nothing about enabling ShedNormal"
        );
    }

    /// WHY: `ShedNormal` buys headroom by dropping relay traffic. It must
    /// never buy it from the classes whose loss is a hard error (Critical:
    /// DM inbox and control plane) or from this node's own speech
    /// (local-origin publishes), because neither is relay load this node can
    /// decline to carry on someone else's behalf.
    #[tokio::test]
    async fn shed_normal_never_drops_critical_or_local_origin_over_budget() {
        let (critical, critical_transport, topic, target) =
            over_budget_pubsub(TopicPriority::Critical, BytePolicy::ShedNormal).await;
        assert!(critical.egress_limiter.enforcing());
        let forwarded_critical = fanout_over_budget(&critical, topic, target, true).await;
        assert_eq!(
            forwarded_critical.byte_rejected, 0,
            "Critical-class traffic must survive an exhausted byte budget"
        );
        assert_eq!(
            forwarded_critical.attempted, 1,
            "surviving the gate is not enough — the Critical frame must reach transport"
        );
        assert_eq!(
            wait_for_sent_frames(&critical_transport, 1).await,
            1,
            "the Critical frame must be delivered"
        );
        assert_eq!(
            critical.leaf_egress_snapshot().invariant_violations,
            0,
            "a protected Critical send must not trip the transport fence"
        );

        let (normal, normal_transport, topic, target) =
            over_budget_pubsub(TopicPriority::Normal, BytePolicy::ShedNormal).await;
        // forwarded = false is the publish path: this node authored the frame.
        let local_origin = fanout_over_budget(&normal, topic, target, false).await;
        assert_eq!(
            local_origin.byte_rejected, 0,
            "a local-origin publish is not relay load and must not be shed"
        );
        assert_eq!(
            local_origin.succeeded, 1,
            "the local-origin frame must be delivered, not lost at the fence"
        );
        assert_eq!(
            wait_for_sent_frames(&normal_transport, 1).await,
            1,
            "the local-origin frame must reach the wire"
        );
        let snapshot = normal.leaf_egress_snapshot();
        assert_eq!(snapshot.invariant_violations, 0);
        assert!(
            snapshot.shed_suppressed >= 1,
            "protected-but-over-budget sends must be attributable in diagnostics"
        );
    }

    /// The headline invariant of the opt-in policy: **under `ObserveOnly`,
    /// observable send behaviour — what is sent, to whom, and whether it waits
    /// — is identical to running with no byte budget at all. Only the meters
    /// differ.**
    ///
    /// WHY: `ObserveOnly` is what an operator turns on to *measure* egress
    /// before deciding whether to shed. If measuring changes behaviour, the
    /// measurement is worthless and the rollout is unsafe. Two regressions
    /// this catches, both of which shipped in the reviewed stack: admitting a
    /// protected peer without a reservation (the transport fence then drops it
    /// — review F1), and entering the ~4 s waiter loop before checking policy
    /// (review H1).
    #[tokio::test]
    async fn observe_only_send_behaviour_matches_no_budget_at_all() {
        async fn run(policy: Option<BytePolicy>) -> (usize, Vec<PeerId>, usize) {
            // The helper configures the policy and drains the bucket past the
            // hard threshold; `None` then clears the budget entirely, which is
            // the "no byte budget at all" control.
            let (pubsub, transport, topic, target) =
                over_budget_pubsub(TopicPriority::Normal, policy.unwrap_or_default()).await;
            if policy.is_none() {
                assert!(pubsub.configure_leaf_egress(None));
                assert!(!pubsub.egress_limiter.enabled());
            }

            let started = Instant::now();
            let counts = fanout_over_budget(&pubsub, topic, target, true).await;
            let elapsed = started.elapsed();
            assert!(
                elapsed < Duration::from_secs(1),
                "no configuration may make the fan-out wait: {elapsed:?}"
            );
            let sent = wait_for_sent_frames(&transport, 1).await;
            let peers: Vec<PeerId> = transport.sent_frames().into_iter().map(|f| f.0).collect();
            (sent, peers, counts.byte_rejected)
        }

        let unbudgeted = run(None).await;
        let observe_only = run(Some(BytePolicy::ObserveOnly)).await;
        assert_eq!(
            observe_only, unbudgeted,
            "ObserveOnly over a saturated budget must send exactly what an \
             unbudgeted node sends, to the same peer, without deferring"
        );

        // And the contrast that proves the comparison is not vacuous.
        let shedding = run(Some(BytePolicy::ShedNormal)).await;
        assert_ne!(
            shedding, unbudgeted,
            "ShedNormal over the same saturated budget must behave differently"
        );

        // Review R1: the same invariant for the *frame-size* ceiling. The
        // local-publish path used to pre-check `max_serialized_frame_bytes`
        // whenever the limiter was merely `enabled()`, so an ObserveOnly node
        // hard-failed an oversized publish that an unbudgeted node sends. That
        // also contradicted the reservation layer, which deliberately ignores
        // the cap for protected sends — a publish is always local-origin, so
        // the cap could never be policy-correct one stage earlier.
        async fn publish_oversized(policy: Option<BytePolicy>) -> (bool, usize) {
            let local = test_peer_id(1);
            let target = test_peer_id(2);
            let transport = RecordingTransport::new(local);
            transport.set_connected_peer_ids(vec![target]);
            let pubsub = PlumtreePubSub::new_with_task_control(
                local,
                Arc::clone(&transport),
                test_signing_key(),
                false,
            );
            let topic = TopicId::new([0x2f; 32]);
            pubsub.initialize_topic_peers(topic, vec![target]).await;
            store_connected_peers_snapshot(
                pubsub.connected_peers_snapshot.as_ref(),
                Some(HashSet::from([target])),
            );
            if let Some(policy) = policy {
                assert!(pubsub.configure_leaf_egress(Some(LeafEgressConfig {
                    soft_bytes_per_second: 0,
                    hard_bytes_per_second: 128 * 1024,
                    burst_bytes: 4 * 1024 * 1024,
                    // Far below the frame published next.
                    max_serialized_frame_bytes: 1024,
                    policy,
                })));
            }
            let published = pubsub
                .publish(topic, Bytes::from(vec![0x33_u8; 64 * 1024]))
                .await
                .is_ok();
            (published, wait_for_sent_frames(&transport, 1).await)
        }

        let unbudgeted_oversized = publish_oversized(None).await;
        assert!(
            unbudgeted_oversized.0,
            "control: an unbudgeted node publishes this frame"
        );
        assert_eq!(
            publish_oversized(Some(BytePolicy::ObserveOnly)).await,
            unbudgeted_oversized,
            "ObserveOnly must not reject an oversized publish an unbudgeted node sends"
        );
    }

    /// WHY (review F2/F3): the recovery gate used to consult only `enforcing()`,
    /// so under ShedNormal it would defer IHAVE/IWANT batches on Critical
    /// topics, deferred-EAGER custody replies serving our own message, and
    /// stranded-publish retries of our own publish. Protection must be
    /// structural — a property of the traffic's class and provenance — not an
    /// accident of how full the bucket happened to be.
    #[tokio::test]
    async fn recovery_gate_protects_critical_and_local_origin_structurally() {
        // Larger than the recovery escrow left after the data drain, so an
        // unprotected recovery reservation genuinely cannot be charged.
        let frame = Bytes::from(vec![0x6c_u8; 2 * 1024 * 1024]);
        let peer = test_peer_id(2);

        for (priority, local_origin, label) in [
            (TopicPriority::Critical, false, "forwarded Critical"),
            (TopicPriority::Normal, true, "local-origin Normal"),
            (TopicPriority::Bulk, true, "local-origin Bulk"),
        ] {
            let (pubsub, _transport, topic, _target) =
                over_budget_pubsub(priority, BytePolicy::ShedNormal).await;
            let (admitted, deferred) =
                PlumtreePubSub::<RecordingTransport>::reserve_recovery_targets(
                    &pubsub.egress_limiter,
                    topic,
                    vec![peer],
                    "IHAVE",
                    &frame,
                    local_origin,
                    priority,
                );
            assert!(deferred.is_empty(), "{label} recovery must not be deferred");
            assert_eq!(admitted.len(), 1);
            assert!(
                admitted[0].1.is_some(),
                "{label} must carry a real reservation, or the transport fence rejects it"
            );
        }

        // The counterpart: forwarded ordinary recovery IS still shed, so the
        // protection above is not simply the feature being off.
        let (pubsub, _transport, topic, _target) =
            over_budget_pubsub(TopicPriority::Normal, BytePolicy::ShedNormal).await;
        let (_admitted, deferred) = PlumtreePubSub::<RecordingTransport>::reserve_recovery_targets(
            &pubsub.egress_limiter,
            topic,
            vec![peer],
            "IHAVE",
            &frame,
            false,
            TopicPriority::Normal,
        );
        assert_eq!(
            deferred.len(),
            1,
            "forwarded ordinary recovery is still shed under ShedNormal"
        );
    }

    /// WHY: the opt-in gate must not be a way of quietly disabling the feature
    /// altogether. Once an operator selects `ShedNormal`, forwarded ordinary
    /// traffic genuinely is shed at the budget and lands on the existing lazy
    /// recovery path, with the drop attributed to its wire purpose.
    #[tokio::test]
    async fn shed_normal_drops_forwarded_ordinary_traffic_over_budget() {
        for priority in [TopicPriority::Normal, TopicPriority::Bulk] {
            let (pubsub, transport, topic, target) =
                over_budget_pubsub(priority, BytePolicy::ShedNormal).await;

            let counts = fanout_over_budget(&pubsub, topic, target, true).await;

            assert!(
                transport.sent_frames().is_empty(),
                "a shed frame must not reach the wire"
            );

            assert_eq!(
                counts.byte_rejected,
                1,
                "forwarded {} traffic must be shed once the budget is exhausted",
                priority.as_str()
            );
            let snapshot = pubsub.leaf_egress_snapshot();
            assert_eq!(
                snapshot.shed_suppressed, 0,
                "a genuine shed is not a suppressed one"
            );
            let eager = snapshot
                .by_topic_and_purpose
                .iter()
                .find(|row| row.topic == topic.to_bytes() && row.purpose == "EAGER")
                .expect("the shed must be attributed to its wire purpose");
            assert!(
                eager.deferred >= 1,
                "the drop must be metered by reason, not just counted"
            );
        }
    }

    #[tokio::test]
    async fn critical_eager_progresses_ahead_of_ordinary_recovery_backlog() {
        let peer_id = test_peer_id(1);
        let target = test_peer_id(2);
        let transport = RecordingTransport::new(peer_id);
        let pubsub = PlumtreePubSub::new_with_task_control(
            peer_id,
            Arc::clone(&transport),
            test_signing_key(),
            false,
        );
        let topic = TopicId::new([0x65; 32]);
        pubsub
            .admission
            .registry()
            .register(topic, TopicPriority::Critical);
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            topics
                .entry(topic)
                .or_insert_with(TopicState::new)
                .eager_peers
                .insert(target);
        }
        store_connected_peers_snapshot(
            pubsub.connected_peers_snapshot.as_ref(),
            Some(HashSet::from([target])),
        );
        assert!(pubsub.configure_leaf_egress(Some(LeafEgressConfig {
            soft_bytes_per_second: 0,
            hard_bytes_per_second: 128 * 1024,
            burst_bytes: 4 * 1024 * 1024,
            max_serialized_frame_bytes: 4 * 1024 * 1024,
            policy: BytePolicy::ShedNormal,
        })));
        let _drain = pubsub
            .egress_limiter
            .try_reserve_data(
                egress::RecoveryIntentKey {
                    peer: [0x81; 32],
                    scope: [0x81; 32],
                    family: [0x82; 32],
                    operation: [0x83; 32],
                },
                3 * 1024 * 1024,
                false,
            )
            .expect("setup drains data tokens while retaining recovery reserve");
        assert!(pubsub
            .egress_limiter
            .try_reserve_recovery(
                egress::RecoveryIntentKey {
                    peer: [0x84; 32],
                    scope: [0x84; 32],
                    family: [0x85; 32],
                    operation: [0x86; 32],
                },
                1024 * 1024,
            )
            .is_ok());
        for index in 0_u16..300 {
            let mut identity = [0_u8; 32];
            identity[..2].copy_from_slice(&index.to_le_bytes());
            let key = egress::RecoveryIntentKey {
                peer: identity,
                scope: identity,
                family: identity,
                operation: identity,
            };
            assert_eq!(
                pubsub.egress_limiter.try_reserve_recovery(key, 1024 * 1024),
                Err(egress::ReserveError::Deferred)
            );
        }
        pubsub
            .egress_limiter
            .refill_after_for_test(Duration::from_secs(1));

        let counts = pubsub
            .publish_local_with_fanout(topic, Bytes::from(vec![7; 11 * 1024]))
            .await
            .expect("Critical EAGER publish remains bounded and succeeds");

        assert_eq!(counts.candidates, 1);
        assert_eq!(counts.attempted, 1);
        assert_eq!(counts.succeeded, 1);
        assert_eq!(transport.send_count_to(target), 1);
        assert_eq!(
            pubsub.egress_limiter.snapshot().pending_recovery_intents,
            300
        );
    }

    #[tokio::test]
    async fn critical_eager_ready_peer_sends_while_other_peer_gate_is_held() {
        let local = test_peer_id(1);
        let ready = test_peer_id(2);
        let stalled = test_peer_id(3);
        let transport = RecordingTransport::new(local);
        let pubsub = Arc::new(PlumtreePubSub::new_with_task_control(
            local,
            Arc::clone(&transport),
            test_signing_key(),
            false,
        ));
        let topic = TopicId::new([0x67; 32]);
        pubsub
            .admission
            .registry()
            .register(topic, TopicPriority::Critical);
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            topics
                .entry(topic)
                .or_insert_with(TopicState::new)
                .eager_peers
                .extend([ready, stalled]);
        }
        store_connected_peers_snapshot(
            pubsub.connected_peers_snapshot.as_ref(),
            Some(HashSet::from([ready, stalled])),
        );
        assert!(pubsub.configure_leaf_egress(Some(LeafEgressConfig {
            soft_bytes_per_second: 0,
            hard_bytes_per_second: 1024 * 1024,
            burst_bytes: 4 * 1024 * 1024,
            max_serialized_frame_bytes: 4 * 1024 * 1024,
            policy: BytePolicy::ShedNormal,
        })));
        let mut held = pubsub
            .outbound_budgets
            .try_acquire(
                stalled,
                OutboundSendClass::Data,
                TopicPriority::Critical,
                Instant::now(),
            )
            .expect("hold stalled peer gate");
        assert!(held.engage_critical_gate(Duration::from_secs(1)).await);
        let publishing = {
            let pubsub = Arc::clone(&pubsub);
            tokio::spawn(async move {
                pubsub
                    .publish_local_with_fanout(topic, Bytes::from_static(b"identity-sized"))
                    .await
            })
        };
        tokio::time::timeout(Duration::from_secs(1), async {
            while transport.send_count_to(ready) == 0 {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("ready peer sends without waiting for stalled peer");
        assert_eq!(transport.send_count_to(stalled), 0);
        drop(held);
        let counts = tokio::time::timeout(Duration::from_secs(1), publishing)
            .await
            .expect("publish completes after gate release")
            .expect("publish task joins")
            .expect("publish succeeds");
        assert_eq!(
            (counts.candidates, counts.attempted, counts.succeeded),
            (2, 2, 2)
        );
    }

    #[tokio::test]
    async fn dropping_critical_publish_cancels_owned_send_and_intent() {
        let local = test_peer_id(1);
        let target = test_peer_id(2);
        let (transport, mut started) = BlockingTransport::new(local);
        let pubsub = Arc::new(PlumtreePubSub::new_with_task_control(
            local,
            Arc::clone(&transport),
            test_signing_key(),
            false,
        ));
        let topic = TopicId::new([0x68; 32]);
        pubsub
            .admission
            .registry()
            .register(topic, TopicPriority::Critical);
        pubsub
            .topics
            .write_topic(&topic)
            .await
            .entry(topic)
            .or_insert_with(TopicState::new)
            .eager_peers
            .insert(target);
        store_connected_peers_snapshot(
            pubsub.connected_peers_snapshot.as_ref(),
            Some(HashSet::from([target])),
        );
        assert!(pubsub.configure_leaf_egress(Some(LeafEgressConfig {
            soft_bytes_per_second: 0,
            hard_bytes_per_second: 1024 * 1024,
            burst_bytes: 8192,
            max_serialized_frame_bytes: 8192,
            policy: BytePolicy::ShedNormal,
        })));
        let publish = {
            let pubsub = Arc::clone(&pubsub);
            tokio::spawn(async move {
                pubsub
                    .publish_local_with_fanout(topic, Bytes::from_static(b"cancel-owned"))
                    .await
            })
        };
        tokio::time::timeout(Duration::from_secs(1), started.recv())
            .await
            .expect("send enters")
            .expect("started record");
        publish.abort();
        let _ = publish.await;
        tokio::time::timeout(Duration::from_secs(1), async {
            while transport.in_flight.load(Ordering::SeqCst) != 0 {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("owned send is cancelled");
        assert_eq!(pubsub.egress_limiter.snapshot().pending_recovery_intents, 0);
    }

    #[tokio::test(start_paused = true)]
    async fn protected_critical_eager_never_waits_for_budget() {
        let local = test_peer_id(1);
        let target = test_peer_id(2);
        let (transport, mut started) = BlockingTransport::new(local);
        let pubsub = Arc::new(PlumtreePubSub::new_with_task_control(
            local,
            Arc::clone(&transport),
            test_signing_key(),
            false,
        ));
        let topic = TopicId::new([0x69; 32]);
        pubsub
            .admission
            .registry()
            .register(topic, TopicPriority::Critical);
        pubsub
            .topics
            .write_topic(&topic)
            .await
            .entry(topic)
            .or_insert_with(TopicState::new)
            .eager_peers
            .insert(target);
        store_connected_peers_snapshot(
            pubsub.connected_peers_snapshot.as_ref(),
            Some(HashSet::from([target])),
        );
        assert!(pubsub.configure_leaf_egress(Some(LeafEgressConfig {
            soft_bytes_per_second: 0,
            hard_bytes_per_second: 8192,
            burst_bytes: 8192,
            max_serialized_frame_bytes: 8192,
            policy: BytePolicy::ShedNormal,
        })));
        let _drain = pubsub
            .egress_limiter
            .try_reserve_data(
                egress::RecoveryIntentKey {
                    peer: [0x91; 32],
                    scope: [0x91; 32],
                    family: [0x92; 32],
                    operation: [0x93; 32],
                },
                6144,
                false,
            )
            .expect("drain leaves only the recovery floor");
        // #504 opt-in policy: a Critical EAGER is protected, so it must NOT
        // enter the waiter loop at all. This test previously asserted the
        // opposite — that the reservation waits and shares the send deadline —
        // but that is exactly the behaviour review F1 identified as harmful:
        // waiting for budget that will be granted anyway burns the send's own
        // deadline, and a wait that timed out returned `Deferred`, which was
        // then byte-rejected. A dropped Critical message is the hard error the
        // priority class exists to prevent.
        let publishing = {
            let pubsub = Arc::clone(&pubsub);
            tokio::spawn(async move {
                pubsub
                    .publish_local_with_fanout(topic, Bytes::from_static(b"deadline"))
                    .await
            })
        };
        // The send enters immediately, without a refill and without the
        // budget being restored.
        tokio::time::timeout(Duration::from_secs(1), started.recv())
            .await
            .expect("a protected Critical send must not wait for budget")
            .expect("started record");
        assert_eq!(
            pubsub.egress_limiter.snapshot().pending_recovery_intents,
            0,
            "a protected send must not register an escrowed recovery intent"
        );
        let snapshot = pubsub.leaf_egress_snapshot();
        assert_eq!(
            snapshot.invariant_violations, 0,
            "the protected send carries a real reservation"
        );
        assert!(
            snapshot.shed_suppressed >= 1,
            "the overrun is still metered"
        );
        transport.release_sends(1);
        let counts = tokio::time::timeout(Duration::from_secs(5), publishing)
            .await
            .expect("publish completes")
            .expect("publish task joins")
            .expect("publish result is typed");
        assert_eq!(counts.byte_rejected, 0, "Critical is never byte-rejected");
        assert_eq!(counts.attempted, 1);
    }

