    #[tokio::test]
    /// #504 opt-in policy: a targeted send is protected, so it never enters
    /// the byte waiter loop and never registers a recovery intent. This test
    /// previously asserted the opposite — that a zero deadline byte-deferred
    /// the send to `TimedOut` and then cancelled the owned intent. The
    /// surviving subject, and the reason the test exists, is that this path
    /// leaks no intent; it is now guaranteed by never creating one.
    async fn targeted_publish_is_protected_and_leaks_no_recovery_intent() {
        let local = test_peer_id(1);
        let target = test_peer_id(2);
        let transport = RecordingTransport::new(local);
        transport.set_connected_peer_ids(vec![target]);
        let pubsub = PlumtreePubSub::new_with_task_control(
            local,
            Arc::clone(&transport),
            test_signing_key(),
            false,
        );
        let topic = TopicId::new([0x67; 32]);
        store_connected_peers_snapshot(
            pubsub.connected_peers_snapshot.as_ref(),
            Some(HashSet::from([target])),
        );
        assert!(pubsub.configure_leaf_egress(Some(LeafEgressConfig {
            soft_bytes_per_second: 0,
            hard_bytes_per_second: 1,
            burst_bytes: 8192,
            max_serialized_frame_bytes: 8192,
            policy: BytePolicy::ShedNormal,
        })));
        let _drain = pubsub
            .egress_limiter
            .try_reserve_data(
                egress::RecoveryIntentKey {
                    peer: [0xa1; 32],
                    scope: [0xa1; 32],
                    family: [0xa2; 32],
                    operation: [0xa3; 32],
                },
                6144,
                false,
            )
            .expect("drain setup tokens");

        let outcome = pubsub
            .publish_local_with_target(
                topic,
                Bytes::from_static(b"bounded-target"),
                target,
                Duration::ZERO,
            )
            .await
            .expect("ordinary publish contract remains successful");

        assert_eq!(
            outcome.target,
            TargetedPublishOutcome::Sent,
            "a targeted send is not shed for bytes"
        );
        assert_eq!(transport.send_count_to(target), 1);
        assert_eq!(
            pubsub.leaf_egress_snapshot().pending_recovery_intents,
            0,
            "a protected send must not register an intent, so none can leak"
        );
        assert_eq!(
            pubsub.leaf_egress_snapshot().invariant_violations,
            0,
            "it still carries a real reservation"
        );
    }

    #[tokio::test]
    async fn targeted_publish_progresses_behind_recovery_backlog_with_same_cached_wire() {
        let local = test_peer_id(1);
        let target = test_peer_id(2);
        let ordinary_peer = test_peer_id(3);
        let transport = RecordingTransport::new(local);
        transport.set_connected_peer_ids(vec![target, ordinary_peer]);
        let pubsub = Arc::new(PlumtreePubSub::new_with_task_control(
            local,
            Arc::clone(&transport),
            test_signing_key(),
            false,
        ));
        let topic = TopicId::new([0x68; 32]);
        store_connected_peers_snapshot(
            pubsub.connected_peers_snapshot.as_ref(),
            Some(HashSet::from([target, ordinary_peer])),
        );
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            topics
                .entry(topic)
                .or_insert_with(TopicState::new)
                .eager_peers
                .insert(ordinary_peer);
        }
        assert!(pubsub.configure_leaf_egress(Some(LeafEgressConfig {
            soft_bytes_per_second: 0,
            hard_bytes_per_second: 1,
            burst_bytes: 16_384,
            max_serialized_frame_bytes: 16_384,
            policy: BytePolicy::ShedNormal,
        })));
        let _drain = pubsub
            .egress_limiter
            .try_reserve_data(
                egress::RecoveryIntentKey {
                    peer: [0xb1; 32],
                    scope: [0xb1; 32],
                    family: [0xb2; 32],
                    operation: [0xb3; 32],
                },
                12_288,
                false,
            )
            .expect("drain setup tokens while preserving the recovery floor");
        let older = egress::RecoveryIntentKey {
            peer: [0xc1; 32],
            scope: [0xc1; 32],
            family: [0xc2; 32],
            operation: [0xc3; 32],
        };
        assert_eq!(
            pubsub.egress_limiter.try_reserve_recovery(older, 5_000),
            Err(egress::ReserveError::Deferred),
            "the exact target must begin behind an older uncharged intent"
        );
        let charged_before = pubsub.leaf_egress_snapshot().charged_bytes;
        let payload = Bytes::from_static(b"targeted-after-backlog");
        let running = {
            let pubsub = Arc::clone(&pubsub);
            let payload = payload.clone();
            tokio::spawn(async move {
                pubsub
                    .publish_local_with_target(topic, payload, target, Duration::from_secs(1))
                    .await
            })
        };
        // #504 opt-in policy: the targeted leg is protected, so it does not
        // queue behind the backlog — it neither waits nor registers a second
        // intent. This previously asserted two coexisting intents; the older
        // backlog intent is now the only one, and the targeted send proceeds
        // past it rather than behind it.
        assert_eq!(
            pubsub.leaf_egress_snapshot().pending_recovery_intents,
            1,
            "only the older backlog intent exists; the protected target adds none"
        );
        pubsub
            .egress_limiter
            .refill_after_for_test(Duration::from_secs(16_384));
        let outcome = running
            .await
            .expect("target task joins")
            .expect("targeted publish remains bounded and valid");

        assert_eq!(outcome.fanout.candidates, 1, "ordinary fanout is retained");
        // The ordinary leg of a *local* publish is policy-protected from byte
        // shedding (#504 opt-in policy), so it is no longer byte-rejected here
        // even behind the recovery backlog. The subject of this test is the
        // targeted leg below, which is unaffected.
        assert_eq!(outcome.fanout.byte_rejected, 0);
        assert_eq!(outcome.target, TargetedPublishOutcome::Sent);
        let frames = transport.sent_frames_of_kind_to(target, MessageKind::Eager);
        assert_eq!(frames.len(), 1);
        let message: GossipMessage =
            postcard::from_bytes(&frames[0]).expect("transported frame is the signed message");
        assert_eq!(message.payload.as_ref(), Some(&payload));
        let cached = {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            topics
                .get_mut(&topic)
                .and_then(|state| state.get_message(&message.header.msg_id))
                .expect("same message id remains cached")
        };
        assert_eq!(
            postcard::to_stdvec(&cached.header).expect("cached header serializes"),
            postcard::to_stdvec(&message.header).expect("wire header serializes"),
            "cached and targeted transport frames retain the identical signed header"
        );
        assert_eq!(cached.payload, payload);
        let after = pubsub.leaf_egress_snapshot();
        assert!(after.charged_bytes > charged_before);
        assert!(
            after.charged_bytes - charged_before <= 16_384,
            "new charging stays within one configured burst"
        );
        assert_eq!(
            after.pending_recovery_intents, 1,
            "target ownership is gone while the deliberately older intent remains"
        );
        pubsub.egress_limiter.cancel_intent_for_test(older);
        assert_eq!(pubsub.leaf_egress_snapshot().pending_recovery_intents, 0);
    }

    #[tokio::test]
    async fn test_cooling_floor_preserves_last_eligible_eager_peer() {
        let peer_id = test_peer_id(1);
        let transport = test_transport().await;
        let pubsub = PlumtreePubSub::new(peer_id, transport, test_signing_key());
        let topic = TopicId::new([0x33; 32]);
        let cooled_peer = test_peer_id(2);
        let floor_peer = test_peer_id(3);
        let _local_subscription = pubsub.subscribe_ready(topic).await;
        pubsub
            .initialize_topic_peers(topic, vec![cooled_peer, floor_peer])
            .await;

        for _ in 0..PEER_TIMEOUT_THRESHOLD {
            pubsub
                .record_topic_send_results(topic, Vec::new(), vec![cooled_peer])
                .await;
        }
        for _ in 0..PEER_TIMEOUT_THRESHOLD {
            pubsub
                .record_topic_send_results(topic, Vec::new(), vec![floor_peer])
                .await;
        }

        let suppressed = pubsub.stage_stats().suppressed_peers;
        assert_eq!(suppressed.len(), 1);
        assert_eq!(suppressed[0].peer_id, cooled_peer.to_string());

        let counts = pubsub
            .publish_local_with_fanout(topic, Bytes::from_static(b"floor"))
            .await
            .expect("floor peer remains eligible");
        assert_eq!(counts.attempted, 1);
        assert_eq!(pubsub.stage_stats().zero_fanout_publishes, 0);
    }

    /// Reviewer's empirical sequence (issue #32 REQUEST CHANGES): 3 eager
    /// peers, mass-cool → floor saves the last one → the floor peer
    /// disconnects → the remaining suppressed peers stay suppressed → fan-out
    /// drops to 0 permanently.
    ///
    /// The eligibility-time rescue in `rescue_suppressed_eager_peer_if_needed_at`
    /// catches this: at publish time, if all eager peers are suppressed but the
    /// topic has live subscribers, the least-bad peer is un-suppressed so
    /// fan-out is never zero while any connected peer exists.
    #[tokio::test]
    async fn test_cooling_floor_survives_floor_peer_disconnection() {
        let peer_id = test_peer_id(1);
        let transport = test_transport().await;
        let pubsub = PlumtreePubSub::new(peer_id, transport, test_signing_key());
        let topic = TopicId::new([0x34; 32]);
        let peer_a = test_peer_id(2);
        let peer_b = test_peer_id(3);
        let floor_peer = test_peer_id(4);

        let _local_subscription = pubsub.subscribe_ready(topic).await;
        pubsub
            .initialize_topic_peers(topic, vec![peer_a, peer_b, floor_peer])
            .await;

        // Suppress peer_a.
        for _ in 0..PEER_TIMEOUT_THRESHOLD {
            pubsub
                .record_topic_send_results(topic, Vec::new(), vec![peer_a])
                .await;
        }
        // Suppress peer_b.
        for _ in 0..PEER_TIMEOUT_THRESHOLD {
            pubsub
                .record_topic_send_results(topic, Vec::new(), vec![peer_b])
                .await;
        }
        // Drive floor_peer to the suppression threshold. The cooling floor
        // blocks the final suppression because it would empty the eligible set.
        for _ in 0..PEER_TIMEOUT_THRESHOLD {
            pubsub
                .record_topic_send_results(topic, Vec::new(), vec![floor_peer])
                .await;
        }

        let suppressed = pubsub.stage_stats().suppressed_peers;
        assert_eq!(suppressed.len(), 2, "floor peer must not be suppressed");
        assert!(
            suppressed.iter().any(|s| s.peer_id == peer_a.to_string()),
            "peer_a must be suppressed"
        );
        assert!(
            suppressed.iter().any(|s| s.peer_id == peer_b.to_string()),
            "peer_b must be suppressed"
        );

        // Floor peer disconnects — set_topic_peers removes it from eager_peers
        // and clears its cooling state, leaving peer_a and peer_b still
        // suppressed. Without the eligibility-time rescue, fan-out is 0 forever.
        pubsub.set_topic_peers(topic, vec![peer_a, peer_b]).await;

        let counts = pubsub
            .publish_local_with_fanout(topic, Bytes::from_static(b"rescue"))
            .await
            .expect("publish returns Ok after floor-peer disconnect");
        assert!(
            counts.attempted >= 1,
            "eligibility-time rescue must un-suppress at least one peer: attempted={}",
            counts.attempted
        );
        assert_eq!(
            pubsub.stage_stats().zero_fanout_publishes,
            0,
            "rescue must prevent the zero-fanout counter from incrementing"
        );
    }

    /// The floor exists to stop a node black-holing its OWN publishes, so it
    /// is scoped to topics with a live local subscriber. A forward-only relay
    /// topic must keep full cooling: the sender is not the origin, other paths
    /// exist, and pinning an unhealthy peer there buys nothing. A dropped
    /// subscription must revert the topic to forward-only immediately rather
    /// than when `clean_cache` next prunes the closed sender.
    #[test]
    fn test_cooling_floor_is_scoped_to_live_local_subscribers() {
        let mut state = TopicState::new();
        let last_eager = test_peer_id(2);
        let other_eager = test_peer_id(3);
        state.eager_peers.insert(last_eager);
        state.eager_peers.insert(other_eager);

        let now = Instant::now();
        let mut cooling = PeerCoolingState::new(now);
        cooling.suppressed_until = Some(now + Duration::from_secs(60));
        state.peer_cooling.insert(other_eager, cooling);

        // Forward-only: no local subscriber, so cooling stays unrestricted
        // even though suppressing `last_eager` empties the eligible set.
        assert!(
            !state.cooling_floor_blocks_at(last_eager, now),
            "relay topics must not pin an unhealthy peer"
        );

        let (tx, rx) = mpsc::unbounded_channel();
        state.subscribers.push(tx);
        assert!(
            state.cooling_floor_blocks_at(last_eager, now),
            "a locally subscribed topic must keep its last eligible eager peer"
        );

        // Closed senders linger in `subscribers` until `clean_cache` runs;
        // the floor must not treat them as local interest.
        drop(rx);
        assert!(
            !state.cooling_floor_blocks_at(last_eager, now),
            "a dropped subscription must revert the topic to forward-only"
        );
    }

    /// Issue #41 (x0x #368, x0x#697 family): churned peers must not retain
    /// per-topic score/cooling state forever, and `peer_scores_v2` entries
    /// must not outlive their topic. Round 3 seeds BOTH states the previous
    /// versions were blind to, so the test distinguishes the correct
    /// predicate from wrong ones:
    ///
    /// - a MEMBER in the probe-due state (suppression expired, no recovery
    ///   probe in flight) — its cooling entry must SURVIVE so it still
    ///   receives its recovery probe and keeps the backoff escalation
    ///   (deleting it regresses the 0.5.80 cooling work, #62/#63);
    /// - a CHURNED peer whose suppression is NULL — exactly what a first
    ///   send timeout creates, the largest churned population — which must
    ///   be PRUNED (keeping it reopens #41's own leak);
    /// - a churned peer with an ACTIVE escalated cooldown — must survive
    ///   with its escalation intact;
    /// - a stale churned peer (expired, probe-free) — must be pruned.
    #[tokio::test]
    async fn churned_peer_state_and_scores_v2_are_bounded_by_idle_sweep() {
        let topics_map = Arc::new(ShardedTopicMap::new());
        let scoring = peer_scoring::PeerScoring::new();
        let live_topic = TopicId::new([64u8; 32]);
        let dying_topic = TopicId::new([65u8; 32]);
        let member_a = test_peer_id(2);
        let member_b = test_peer_id(3);
        let now = Instant::now();
        const NULL_CHURN: usize = 20;
        const SUPPRESSED_CHURN: usize = 20;
        const STALE_CHURN: usize = 10;
        const PROBE_CHURN: usize = 5;

        {
            let mut guard = topics_map.write_topic(&live_topic).await;
            let state = guard.entry(live_topic).or_insert_with(TopicState::new);
            state.eager_peers.insert(member_a);
            state.lazy_peers.insert(member_b);
            state.peer_scores.insert(member_a, PeerScore::new_at(now));
            state.peer_scores.insert(member_b, PeerScore::new_at(now));
            // member_a is PROBE-DUE: suppression expired, no probe claimed.
            let mut probe_due = PeerCoolingState::new(now);
            probe_due.suppressed_until = Some(now - Duration::from_millis(1));
            probe_due.cooldown = Duration::from_secs(240);
            state.peer_cooling.insert(member_a, probe_due);
            state
                .peer_cooling
                .insert(member_b, PeerCoolingState::new(now));
            for i in 0..NULL_CHURN {
                let churned = test_peer_id(10 + i as u8);
                // Fresh PeerCoolingState: suppression is NULL — the state a
                // FIRST send timeout creates before any suppression fires.
                state.peer_scores.insert(churned, PeerScore::new_at(now));
                state
                    .peer_cooling
                    .insert(churned, PeerCoolingState::new(now));
            }
            for i in 0..SUPPRESSED_CHURN {
                let churned = test_peer_id(40 + i as u8);
                let mut cooling = PeerCoolingState::new(now);
                cooling.suppressed_until = Some(now + Duration::from_secs(60));
                cooling.cooldown = Duration::from_secs(240);
                state.peer_scores.insert(churned, PeerScore::new_at(now));
                state.peer_cooling.insert(churned, cooling);
            }
            for i in 0..STALE_CHURN {
                let churned = test_peer_id(70 + i as u8);
                let mut cooling = PeerCoolingState::new(now);
                cooling.suppressed_until = Some(now - Duration::from_millis(1));
                state.peer_scores.insert(churned, PeerScore::new_at(now));
                state.peer_cooling.insert(churned, cooling);
            }
            for i in 0..PROBE_CHURN {
                let churned = test_peer_id(90 + i as u8);
                let mut cooling = PeerCoolingState::new(now);
                // A recovery probe is IN FLIGHT for this churned peer: the
                // suppression already expired but the probe outcome is
                // pending — only the `recovery_probe_in_flight` clause of
                // the predicate keeps it (dropping the entry would strand
                // the in-flight probe marker).
                cooling.suppressed_until = Some(now - Duration::from_millis(1));
                cooling.recovery_probe_in_flight = true;
                state.peer_scores.insert(churned, PeerScore::new_at(now));
                state.peer_cooling.insert(churned, cooling);
            }
        }
        {
            let mut guard = topics_map.write_topic(&dying_topic).await;
            let state = guard.entry(dying_topic).or_insert_with(TopicState::new);
            state.last_activity = now - Duration::from_secs(TOPIC_IDLE_TTL_SECS + 1);
        }

        // v2 entries: one live member, 50 churned-on-live-topic (recently
        // touched), and one on the dying topic.
        scoring.note_mesh_join(live_topic, member_a);
        for i in 0..50u8 {
            scoring.record_first_delivery(live_topic, test_peer_id(10 + i));
        }
        scoring.record_first_delivery(dying_topic, member_a);
        assert_eq!(scoring.entry_count(), 52);

        // The cache cleaner's per-shard pass (the exact function it calls).
        let reaped = {
            let mut all = topics_map.write_all().await;
            let mut reaped = Vec::new();
            for shard in all.iter_mut() {
                reaped.extend(clean_and_reap_topic_ids(
                    shard,
                    Duration::from_secs(TOPIC_IDLE_TTL_SECS),
                ));
            }
            reaped
        };
        assert_eq!(reaped, vec![dying_topic], "the idle topic is reaped");

        {
            let guard = topics_map.read_topic(&live_topic).await;
            let state = guard.get(&live_topic).expect("live topic survives");
            assert_eq!(
                state.peer_scores.len(),
                2,
                "all churned per-topic scores pruned to the live members"
            );
            assert_eq!(
                state.peer_cooling.len(),
                2 + SUPPRESSED_CHURN + PROBE_CHURN,
                "null-suppression and stale churned cooling pruned; the probe-due MEMBER, the plain member, actively-suppressed churned, and probe-in-flight churned cooling survive"
            );
            // The member's probe-due entry survives VERBATIM — expiry and
            // backoff escalation intact, so its recovery probe still fires.
            let probe_due = state
                .peer_cooling
                .get(&member_a)
                .expect("the probe-due member's cooling entry must survive");
            assert_eq!(
                probe_due.cooldown,
                Duration::from_secs(240),
                "the member's backoff escalation must survive the sweep"
            );
            assert!(
                probe_due.suppression_expired_at(now),
                "the member stays probe-due (expired, no probe in flight)"
            );
            // The suppressed churned survivor keeps its escalation too.
            let escalated = state
                .peer_cooling
                .get(&test_peer_id(40))
                .expect("suppressed churned cooling entry survives");
            assert_eq!(escalated.cooldown, Duration::from_secs(240));
            // The null-suppression churned entry is GONE — the largest
            // churned population must not leak.
            assert!(
                !state.peer_cooling.contains_key(&test_peer_id(10)),
                "a churned peer's null-suppression entry must be pruned"
            );
            // The probe-in-flight churned entry SURVIVES — dropping it
            // would strand the in-flight recovery probe marker.
            let probing = state
                .peer_cooling
                .get(&test_peer_id(90))
                .expect("probe-in-flight churned cooling entry survives");
            assert!(probing.recovery_probe_in_flight);
        }

        // The v2 bound through the exact helper the cleaner calls.
        let (aged_out, reaped_scores) = prune_churned_peer_scoring(
            &topics_map,
            &scoring,
            &reaped,
            now,
            PEER_SCORE_V2_RETENTION,
        )
        .await;
        assert_eq!(aged_out, 0, "nothing is old enough to age out yet");
        assert_eq!(reaped_scores, 1, "the reaped topic's entries are dropped");
        assert_eq!(scoring.entry_count(), 51);
    }

    /// Issue #41 round 2 (BLOCKING): the `peer_scores_v2` idle window must
    /// elapse even while the diagnostics path is polled. `snapshot()`
    /// rewrites `last_decay_at` on every entry to keep the decayed
    /// counters current, and x0x calls `stage_stats()` every 5 s — so a
    /// `last_decay_at`-based "last touch" never ages and the bound does
    /// not bound (500/500 churned entries retained across 20
    /// poll-then-prune cycles at 4x the window, per review). The GC now
    /// uses the evidence-only `last_activity` stamp, which the metrics
    /// path never touches. This test POLLS the real `stage_stats()` path
    /// between prune cycles — a test that does not poll passes either
    /// way.
    #[tokio::test]
    async fn peer_scores_v2_idle_window_elapses_despite_diagnostics_polling() {
        let peer_id = test_peer_id(1);
        let transport = RecordingTransport::new(peer_id);
        let pubsub = PlumtreePubSub::new_with_task_control(
            peer_id,
            Arc::clone(&transport),
            test_signing_key(),
            false,
        );
        let topic = TopicId::new([70u8; 32]);
        const CHURNED: usize = 50;
        // Record evidence for CHURNED (topic, peer) pairs — no mesh
        // membership anywhere, so only the idle window can retain them.
        for i in 0..CHURNED as u8 {
            pubsub
                .peer_scoring
                .record_first_delivery(topic, test_peer_id(10 + i));
        }
        assert_eq!(pubsub.peer_scoring.entry_count(), CHURNED);

        // A window far shorter than the poll-to-poll gap below.
        let window = Duration::from_millis(25);
        // Let the evidence age past the window while POLLING the real
        // diagnostics path — exactly the x0x supervisor's behaviour.
        for _ in 0..6 {
            let _ = pubsub.stage_stats();
            tokio::time::sleep(Duration::from_millis(15)).await;
        }
        let _ = pubsub.stage_stats();

        // The cleaner's exact helper, empty live set, real now.
        let (aged_out, _reaped) = prune_churned_peer_scoring(
            &pubsub.topics,
            &pubsub.peer_scoring,
            &[],
            Instant::now(),
            window,
        )
        .await;
        assert_eq!(
            aged_out, CHURNED,
            "churned entries must age out even while stage_stats() is polled — the idle clock cannot be the decay clock"
        );
        assert_eq!(pubsub.peer_scoring.entry_count(), 0);
    }

    /// Issue #41 round 3: the pending-IHAVE queue is bounded. Ids queued
    /// faster than a flush consumes them (structurally on an all-eager
    /// topic, and under admission denial once consumption is deferred past
    /// early-exit paths) must not grow the vector without bound; overflow
    /// drops the OLDEST ids, which are the stalest advertisements, and the
    /// drops are counted so operators can see sustained overflow.
    #[test]
    fn pending_ihave_queue_is_bounded() {
        let mut state = TopicState::new();
        let total = MAX_PENDING_IHAVE + 500;
        let mut dropped_total = 0;
        for i in 0..total {
            let mut msg_id = [68u8; 32];
            msg_id[0] = (i % 256) as u8;
            msg_id[1] = (i / 256) as u8;
            dropped_total += state.push_pending_ihave(msg_id);
        }
        assert_eq!(
            state.pending_ihave.len(),
            MAX_PENDING_IHAVE,
            "the queue must cap at MAX_PENDING_IHAVE, not grow with input"
        );
        // The OLDEST ids were dropped: the front is the 500th id pushed.
        let mut expected_front = [68u8; 32];
        expected_front[0] = (500 % 256) as u8;
        expected_front[1] = (500 / 256) as u8;
        assert_eq!(
            state.pending_ihave.front(),
            Some(&expected_front),
            "overflow drops the oldest (stalest) ids"
        );
        assert_eq!(
            dropped_total, 500,
            "every evicted id is counted for the diagnostics surface"
        );
    }

    #[tokio::test]
    async fn partial_budget_ihave_flush_preserves_each_recipient_exactly_once() {
        let local = test_peer_id(1);
        let peers = [test_peer_id(2), test_peer_id(3)];
        let topic = TopicId::new([0x51; 32]);
        let transport = RecordingTransport::new(local);
        transport.set_connected_peer_ids(peers.to_vec());
        let pubsub = PlumtreePubSub::new_with_task_control(
            local,
            transport.clone(),
            test_signing_key(),
            false,
        );
        pubsub.initialize_topic_peers(topic, peers.to_vec()).await;
        let msg_id = [0x52; 32];
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics.get_mut(&topic).expect("topic state");
            state.eager_peers.clear();
            state.lazy_peers.extend(peers);
            state.push_pending_ihave(msg_id);
        }
        let payload: Bytes = postcard::to_stdvec(&vec![msg_id])
            .expect("IHAVE payload")
            .into();
        let mut header = MessageHeader {
            version: 1,
            payload_hash: None,
            topic,
            msg_id,
            kind: MessageKind::IHave,
            hop: 0,
            ttl: 10,
        };
        header.seal_payload_hash(Some(payload.as_ref()));
        let frame_len = postcard::to_stdvec(&GossipMessage {
            signature: pubsub.sign_message(&header),
            public_key: pubsub.signing_key.public_key().to_vec(),
            header,
            payload: Some(payload),
        })
        .expect("IHAVE frame")
        .len();
        // Exact one-frame burst: the second target must remain pending until
        // a later refill, independent of signing or scheduler duration.
        assert!(pubsub.configure_leaf_egress(Some(LeafEgressConfig {
            soft_bytes_per_second: 0,
            hard_bytes_per_second: u64::try_from(frame_len).expect("frame size") * 100,
            burst_bytes: u64::try_from(frame_len).expect("frame size"),
            max_serialized_frame_bytes: frame_len,
            policy: BytePolicy::ShedNormal,
        })));

        let mut late_rotation = LateOfferRotation::default();
        PlumtreePubSub::<RecordingTransport>::flush_ihave_batches(
            &pubsub.topics,
            &pubsub.transport,
            &pubsub.signing_key,
            &pubsub.stage_stats,
            &pubsub.outbound_budgets,
            IhaveFlushEnv {
                send_path: &pubsub.send_path_context(),
                egress_limiter: &pubsub.egress_limiter,
                late_rotation: &mut late_rotation,
            },
        )
        .await;
        assert_eq!(transport.sent_frames().len(), 1);
        assert!(!pubsub
            .topics
            .read_topic(&topic)
            .await
            .get(&topic)
            .expect("topic state")
            .pending_ihave
            .is_empty());
        pubsub.egress_limiter.refill_one_second_for_test();
        PlumtreePubSub::<RecordingTransport>::flush_ihave_batches(
            &pubsub.topics,
            &pubsub.transport,
            &pubsub.signing_key,
            &pubsub.stage_stats,
            &pubsub.outbound_budgets,
            IhaveFlushEnv {
                send_path: &pubsub.send_path_context(),
                egress_limiter: &pubsub.egress_limiter,
                late_rotation: &mut late_rotation,
            },
        )
        .await;
        for peer in peers {
            assert_eq!(
                transport
                    .sent_frames_of_kind_to(peer, MessageKind::IHave)
                    .len(),
                1,
                "each recipient gets one successful IHAVE handoff"
            );
        }
        let topics = pubsub.topics.read_topic(&topic).await;
        assert!(topics
            .get(&topic)
            .expect("topic state")
            .pending_ihave
            .is_empty());
    }

    /// WHY (recovery-intent admission starvation): intent admission used to
    /// be first-come-first-served up to the class caps with no eviction, so
    /// while the map was saturated a newly observed, otherwise-eligible
    /// IHAVE target was refused with `IntentLimit` no matter how much byte
    /// budget was available. Under sustained background recovery demand the
    /// new target was excluded for as long as it took an incumbent intent
    /// to age out — metadata starvation, worst on exactly the busy relays
    /// that matter most. Fair-share displacement admits an under-represented
    /// target by displacing the least-work intent of the most-represented
    /// bucket instead of refusing.
    ///
    /// The limiter runs on a fully injected virtual clock: every internal
    /// clock read resolves to the injected time, so token boundaries, slot
    /// boundaries, and expiry all advance on one deterministic timeline with
    /// zero real-time contamination (an earlier version let a few microseconds
    /// of real elapsed time shift token boundaries, which could hand the
    /// promoted target a PARTIAL first charge and, before the promotion rule
    /// was fixed, send it to the back of the rotation). The scenario is
    /// parameterised over background-frame scales; the final
    /// `intent_displaced >= 1` assert pins the pass to the displacement
    /// path, not to expiry.
    ///
    /// WHAT THIS TEST GATES: admission starvation only — a continuously
    /// observed eligible target must ENTER a saturated class via
    /// displacement and reach the transport. It does NOT gate the
    /// promotion rule: with the promotion rule reverted it still passes
    /// (verified, review r4 evidence matrix), because a
    /// single-quantum-scale IHAVE frame usually completes on its first
    /// visit. The promotion rule — partial-charge survival, per-intent
    /// keying, visit cap, no same-scope inheritance — is gated by
    /// `promoted_scope_survives_partial_charge_until_fully_charged` and
    /// `same_scope_fresh_peer_wedge_keeps_incumbents_completing` in
    /// `egress_fairness_tests.rs`.
    async fn run_full_admission_reproducer(background_frame: usize, hard_rate: u64, burst: u64) {
        const FIELD_WINDOW_SECONDS: u16 = 120;

        let local = test_peer_id(1);
        let required = test_peer_id(2);
        let topic = TopicId::new([0xd1; 32]);
        let transport = RecordingTransport::new(local);
        transport.set_connected_peer_ids(vec![required]);
        let pubsub = PlumtreePubSub::new_with_task_control(
            local,
            Arc::clone(&transport),
            test_signing_key(),
            false,
        );
        pubsub.initialize_topic_peers(topic, vec![required]).await;
        assert!(pubsub.configure_leaf_egress(Some(LeafEgressConfig {
            soft_bytes_per_second: 0,
            hard_bytes_per_second: hard_rate,
            burst_bytes: burst,
            max_serialized_frame_bytes: background_frame,
            policy: BytePolicy::ShedNormal,
        })));
        // Anchor the virtual clock at the configured state; from here on
        // the limiter never reads the real clock.
        pubsub
            .egress_limiter
            .advance_virtual_clock_for_test(Duration::from_millis(0));

        // Positive production-path control: this exact membership and IHAVE
        // path reaches the required peer when recovery admission has room.
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics.get_mut(&topic).expect("target topic state");
            state.eager_peers.clear();
            state.lazy_peers.insert(required);
            state.push_pending_ihave([0xd2; 32]);
        }
        let mut late_rotation = LateOfferRotation::default();
        PlumtreePubSub::<RecordingTransport>::flush_ihave_batches(
            &pubsub.topics,
            &pubsub.transport,
            &pubsub.signing_key,
            &pubsub.stage_stats,
            &pubsub.outbound_budgets,
            IhaveFlushEnv {
                send_path: &pubsub.send_path_context(),
                egress_limiter: &pubsub.egress_limiter,
                late_rotation: &mut late_rotation,
            },
        )
        .await;
        assert_eq!(
            transport
                .sent_frames_of_kind_to(required, MessageKind::IHave)
                .len(),
            1,
            "control proves target membership, eligibility, and transport send"
        );

        // Fill the same production recovery admission path with the chosen
        // background scale. Twenty-six distinct target identities are
        // retained in the fixture; the remaining entries model other active
        // topics.
        let background_frame_bytes = Bytes::from(vec![0xa5; background_frame]);
        let mut sequence = 0_u32;
        while pubsub.egress_limiter.snapshot().pending_recovery_intents < 960 {
            let peer = test_peer_id(10 + (sequence % 26) as u8);
            let mut scope = [0_u8; 32];
            scope[..4].copy_from_slice(&sequence.to_le_bytes());
            let background_topic = TopicId::new(scope);
            let _ = PlumtreePubSub::<RecordingTransport>::reserve_recovery_targets(
                &pubsub.egress_limiter,
                background_topic,
                vec![peer],
                "IHAVE",
                &background_frame_bytes,
                false,
                TopicPriority::Normal,
            );
            sequence += 1;
        }
        let mut critical_sequence = 0_u32;
        while pubsub.egress_limiter.snapshot().pending_recovery_intents < 1024 {
            let mut identity = [0xc1; 32];
            identity[..4].copy_from_slice(&critical_sequence.to_le_bytes());
            let key = egress::RecoveryIntentKey {
                peer: identity,
                scope: identity,
                family: identity,
                operation: identity,
            };
            let _ = pubsub
                .egress_limiter
                .try_reserve_critical_for_test(key, background_frame);
            critical_sequence += 1;
        }

        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            topics
                .get_mut(&topic)
                .expect("target topic state")
                .push_pending_ihave([0xd3; 32]);
        }
        let baseline = transport
            .sent_frames_of_kind_to(required, MessageKind::IHave)
            .len();

        for _ in 0..FIELD_WINDOW_SECONDS {
            pubsub
                .egress_limiter
                .advance_virtual_clock_for_test(Duration::from_secs(1));
            // Sustained existing demand takes newly free metadata before the
            // continuously observed new target is offered by the real flusher.
            let mut identity = [0xc1; 32];
            identity[..4].copy_from_slice(&critical_sequence.to_le_bytes());
            let _ = pubsub.egress_limiter.try_reserve_critical_for_test(
                egress::RecoveryIntentKey {
                    peer: identity,
                    scope: identity,
                    family: identity,
                    operation: identity,
                },
                background_frame,
            );
            critical_sequence += 1;
            while pubsub.egress_limiter.snapshot().pending_recovery_intents < 1024 {
                let peer = test_peer_id(10 + (sequence % 26) as u8);
                let mut scope = [0_u8; 32];
                scope[..4].copy_from_slice(&sequence.to_le_bytes());
                let _ = PlumtreePubSub::<RecordingTransport>::reserve_recovery_targets(
                    &pubsub.egress_limiter,
                    TopicId::new(scope),
                    vec![peer],
                    "IHAVE",
                    &background_frame_bytes,
                    false,
                    TopicPriority::Normal,
                );
                sequence += 1;
            }
            PlumtreePubSub::<RecordingTransport>::flush_ihave_batches(
                &pubsub.topics,
                &pubsub.transport,
                &pubsub.signing_key,
                &pubsub.stage_stats,
                &pubsub.outbound_budgets,
                IhaveFlushEnv {
                    send_path: &pubsub.send_path_context(),
                    egress_limiter: &pubsub.egress_limiter,
                    late_rotation: &mut late_rotation,
                },
            )
            .await;
            if transport
                .sent_frames_of_kind_to(required, MessageKind::IHave)
                .len()
                > baseline
            {
                break;
            }
        }

        // The pass must come through displacement, never through the
        // background ageing out: a green by expiry would be a false green
        // for the admission fix.
        assert!(
            pubsub.egress_limiter.snapshot().intent_displaced >= 1,
            "the required target must have been admitted by displacement"
        );
        let (deque_len, position, req_intents) = pubsub
            .egress_limiter
            .ordinary_rotation_probe_for_test(topic.to_bytes());
        assert!(
            transport
                .sent_frames_of_kind_to(required, MessageKind::IHave)
                .len()
                > baseline,
            "required target was excluded for 120 s despite sufficient byte share; \
             displaced={} pending={} rotation={:?}/{deque_len} required={:?} promoted={:?}",
            pubsub.egress_limiter.snapshot().intent_displaced,
            pubsub.egress_limiter.snapshot().pending_recovery_intents,
            position,
            req_intents,
            pubsub
                .egress_limiter
                .debug_promotion_for_test()
                .map(|(key, visits)| (key.scope[..4].to_vec(), visits)),
        );
    }

