    #[tokio::test]
    async fn late_eager_peer_receives_local_only_ihave_and_pull_path() {
        let publisher_id = test_peer_id(1);
        let receiver_id = test_peer_id(2);
        let topic = TopicId::new([0x7e; 32]);
        let publisher_transport = RecordingTransport::new(publisher_id);
        publisher_transport.set_connected_peer_ids(vec![receiver_id]);
        let publisher = PlumtreePubSub::new_with_task_control(
            publisher_id,
            publisher_transport.clone(),
            test_signing_key(),
            false,
        );
        let payload = Bytes::from_static(b"late-local-history");
        let local_id = publisher.calculate_msg_id(&topic, &payload);
        publisher
            .publish_local(topic, payload.clone())
            .await
            .expect("cache local history");
        {
            let mut topics = publisher.topics.write_topic(&topic).await;
            let state = topics.get_mut(&topic).expect("published topic");
            state.pending_ihave.clear();
            let remote_id = [0x7f; 32];
            state.cache_message(
                remote_id,
                Bytes::from_static(b"remote-cache"),
                test_header(topic, remote_id),
                false,
            );
            let dropped_id = [0x80; 32];
            state.cache_message(
                dropped_id,
                Bytes::from_static(b"dropped-local"),
                test_header(topic, dropped_id),
                true,
            );
            state.mark_message_dropped(&dropped_id);
        }

        publisher.set_topic_peers(topic, vec![receiver_id]).await;
        {
            let topics = publisher.topics.read_topic(&topic).await;
            assert!(topics
                .get(&topic)
                .expect("topic")
                .eager_peers
                .contains(&receiver_id));
        }
        let mut late_rotation = LateOfferRotation::default();
        PlumtreePubSub::<RecordingTransport>::flush_ihave_batches(
            &publisher.topics,
            &publisher.transport,
            &publisher.signing_key,
            &publisher.stage_stats,
            &publisher.outbound_budgets,
            IhaveFlushEnv {
                send_path: &publisher.send_path_context(),
                egress_limiter: &publisher.egress_limiter,
                late_rotation: &mut late_rotation,
            },
        )
        .await;
        let ihaves = publisher_transport.sent_frames_of_kind_to(receiver_id, MessageKind::IHave);
        assert_eq!(ihaves.len(), 1, "late peer receives one targeted offer");
        let offered: GossipMessage = postcard::from_bytes(&ihaves[0]).expect("signed IHAVE");
        let ids: Vec<MessageIdType> =
            postcard::from_bytes(offered.payload.as_deref().expect("IHAVE payload"))
                .expect("IHAVE ids");
        assert_eq!(
            ids,
            vec![local_id],
            "remote and dropped cache ids stay private"
        );

        let receiver_transport = RecordingTransport::new(receiver_id);
        receiver_transport.set_connected_peer_ids(vec![publisher_id]);
        let receiver = PlumtreePubSub::new_with_task_control(
            receiver_id,
            receiver_transport.clone(),
            test_signing_key(),
            false,
        );
        let mut subscription = receiver.subscribe(topic);
        receiver
            .dispatch_message(publisher_id, None, ihaves[0].clone())
            .await
            .expect("receiver handles signed IHAVE");
        let iwants = receiver_transport.sent_frames_of_kind_to(publisher_id, MessageKind::IWant);
        assert_eq!(iwants.len(), 1);
        let eager_len = {
            let mut topics = publisher.topics.write_topic(&topic).await;
            let cached = topics
                .get_mut(&topic)
                .expect("topic")
                .get_local_origin_message(&local_id)
                .expect("local cached message");
            postcard::to_stdvec(&GossipMessage {
                signature: publisher.sign_message(&cached.header),
                public_key: publisher.signing_key.public_key().to_vec(),
                header: cached.header,
                payload: Some(cached.payload),
            })
            .expect("EAGER frame")
            .len()
        };
        assert!(publisher.configure_leaf_egress(Some(LeafEgressConfig {
            soft_bytes_per_second: 0,
            hard_bytes_per_second: 1,
            burst_bytes: u64::try_from(eager_len).expect("frame size"),
            max_serialized_frame_bytes: eager_len,
            policy: BytePolicy::ShedNormal,
        })));
        let drain = PlumtreePubSub::<RecordingTransport>::recovery_intent_key(
            topic,
            receiver_id,
            "EAGER",
            b"consume-reply-burst",
        );
        let _charged = publisher
            .egress_limiter
            .reserve_critical_eager(drain, eager_len, Duration::from_secs(1))
            .await
            .expect("competing Critical frame consumes reply burst");
        // #504 opt-in policy: the payload being pulled is this node's OWN
        // message, so the byte budget may not shed the reply even though the
        // bucket above is exhausted. This stage used to assert the opposite
        // (deferral into `deferred_eager_replies`, then a retry on the next
        // flush); protecting local origin makes that unreachable here. The
        // subject of the test — the late peer receives the local-only message
        // through the restricted pull path, charged exactly once — is kept.
        assert!(publisher
            .handle_local_origin_iwant(receiver_id, iwants[0].clone())
            .await
            .expect("restricted pull of a local-origin payload is served"));
        {
            let topics = publisher.topics.read_topic(&topic).await;
            let replies = &topics.get(&topic).expect("topic").deferred_eager_replies;
            assert!(
                replies.is_empty(),
                "a protected local-origin reply is sent, so nothing enters custody"
            );
        }
        let eager = publisher_transport.sent_messages_of_kind_to(receiver_id, MessageKind::Eager);
        assert_eq!(eager.len(), 1);
        assert_eq!(eager[0].payload.as_ref(), Some(&payload));
        let eager_after_retry = publisher
            .leaf_egress_snapshot()
            .by_topic_and_purpose
            .into_iter()
            .find(|row| row.topic == topic.to_bytes() && row.purpose == "EAGER")
            .expect("EAGER byte accounting");
        assert_eq!(
            eager_after_retry.sent_bytes,
            u64::try_from(eager_len).expect("frame size"),
            "the protected reply is charged exactly once"
        );
        let eager_frame = publisher_transport
            .sent_frames_of_kind_to(receiver_id, MessageKind::Eager)
            .into_iter()
            .next()
            .expect("retried EAGER frame");
        receiver
            .dispatch_message(publisher_id, None, eager_frame)
            .await
            .expect("receiver handles retried EAGER");
        let (delivered_from, delivered_payload) =
            tokio::time::timeout(Duration::from_secs(1), subscription.recv())
                .await
                .expect("subscriber delivery deadline")
                .expect("subscription remains live");
        assert_eq!(delivered_from, publisher_id);
        assert_eq!(delivered_payload, payload);

        // The first successful flush advances the cursor. The next scan proves
        // it complete and removes it; unchanged membership cannot re-add it.
        PlumtreePubSub::<RecordingTransport>::flush_ihave_batches(
            &publisher.topics,
            &publisher.transport,
            &publisher.signing_key,
            &publisher.stage_stats,
            &publisher.outbound_budgets,
            IhaveFlushEnv {
                send_path: &publisher.send_path_context(),
                egress_limiter: &publisher.egress_limiter,
                late_rotation: &mut late_rotation,
            },
        )
        .await;
        publisher.set_topic_peers(topic, vec![receiver_id]).await;
        PlumtreePubSub::<RecordingTransport>::flush_ihave_batches(
            &publisher.topics,
            &publisher.transport,
            &publisher.signing_key,
            &publisher.stage_stats,
            &publisher.outbound_budgets,
            IhaveFlushEnv {
                send_path: &publisher.send_path_context(),
                egress_limiter: &publisher.egress_limiter,
                late_rotation: &mut late_rotation,
            },
        )
        .await;
        assert_eq!(
            publisher_transport
                .sent_frames_of_kind_to(receiver_id, MessageKind::IHave)
                .len(),
            1,
            "repeated peer refresh must not resend completed history"
        );
        assert_eq!(
            publisher_transport
                .sent_frames_of_kind_to(receiver_id, MessageKind::Eager)
                .len(),
            1,
            "successful reply retry retires custody"
        );
    }

    #[tokio::test]
    async fn late_local_offer_disconnect_and_cache_expiry_remove_custody() {
        let local = test_peer_id(1);
        let peer = test_peer_id(2);
        let topic = TopicId::new([0x81; 32]);
        let transport = RecordingTransport::new(local);
        let pubsub =
            PlumtreePubSub::new_with_task_control(local, transport, test_signing_key(), false);
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics.entry(topic).or_insert_with(|| {
                TopicState::with_cache_config(PubSubCacheConfig {
                    max_messages_per_topic: NonZeroUsize::new(4).expect("nonzero"),
                    max_bytes_per_topic: 64 * 1024,
                    max_age: Duration::from_secs(1),
                })
            });
            let id = [0x82; 32];
            state.message_cache.insert_at(
                id,
                CachedMessage {
                    payload: Bytes::from_static(b"expired-local"),
                    header: test_header(topic, id),
                    dropped: false,
                    local_origin: true,
                    inner_proof: None,
                },
                Instant::now() - Duration::from_secs(2),
            );
            state.late_local_offers.insert(
                peer,
                LateLocalOffer {
                    cutoff: Instant::now(),
                    cursor: None,
                    failures: 0,
                    next_attempt: None,
                },
            );
            assert!(state.late_local_offer_batch(peer, Instant::now()).is_none());
            assert!(state.late_local_offers.is_empty());
            state.cache_message(
                [0x83; 32],
                Bytes::from_static(b"live"),
                test_header(topic, [0x83; 32]),
                true,
            );
        }
        pubsub.set_topic_peers(topic, vec![peer]).await;
        {
            let topics = pubsub.topics.read_topic(&topic).await;
            assert!(topics
                .get(&topic)
                .expect("topic")
                .late_local_offers
                .contains_key(&peer));
        }
        pubsub.set_topic_peers(topic, Vec::new()).await;
        let topics = pubsub.topics.read_topic(&topic).await;
        assert!(topics
            .get(&topic)
            .expect("topic")
            .late_local_offers
            .is_empty());
    }

    /// WHY: `late_local_offers` is a per-peer pagination cursor. Every other
    /// per-peer custody map in `TopicState` is capped and age-pruned because
    /// an uncapped one grows with peer *churn* rather than with outstanding
    /// work — the "record outlives the connection" shape that has bitten this
    /// codebase before. Without the cap this map grows one entry per peer that
    /// ever asked, for the life of the topic.
    ///
    /// Polls the map itself, not a meter: a meter can be right while the map
    /// leaks.
    #[test]
    fn late_local_offers_stay_bounded_under_peer_churn() {
        let topic = TopicId::new([0x4d; 32]);
        let mut state = TopicState::new();
        let now = Instant::now();
        state.cache_message(
            [0x01; 32],
            Bytes::from_static(b"local"),
            test_header(topic, [0x01; 32]),
            true,
        );

        // Far more distinct peers than the cap, as continuous churn would.
        for index in 0..(MAX_LATE_LOCAL_OFFERS * 4) {
            let mut raw = [0_u8; 32];
            raw[..8].copy_from_slice(&(index as u64).to_le_bytes());
            state.queue_late_local_offer(PeerId::new(raw), now);
        }
        assert!(
            state.late_local_offers.len() <= MAX_LATE_LOCAL_OFFERS,
            "peer churn must not grow the offer map without bound: {} entries",
            state.late_local_offers.len()
        );

        // An offer whose cutoff has aged past the cache it pages over can
        // never yield another batch, so it must not be retained either.
        let aged = now + state.message_cache.max_age + Duration::from_secs(1);
        state.prune_late_local_offers(aged);
        assert!(
            state.late_local_offers.is_empty(),
            "offers older than the cache they page over must be evicted"
        );
    }

    /// Relay overhead invariant I1: with the Leaf egress limiter disabled,
    /// a scripted publish + inbound IHAVE (IWANT reply) + inbound IWANT
    /// (cached EAGER serve) + N flush ticks must acquire ZERO limiter state
    /// mutexes and exactly ONE all-shard `write_all()` per flush tick (the
    /// 0.5.82 shape), never two.
    ///
    /// Revert-fails: restoring a mutex-locked `enabled()`/`enforcing()`/
    /// `validate_reservation`/`record_send_outcome` makes the mutex count
    /// positive; restoring the unconditional `flush_deferred_eager_replies`
    /// write_all doubles the take count.
    #[tokio::test]
    async fn disabled_limiter_costs_zero_mutexes_and_one_write_all_per_flush() {
        let local = test_peer_id(1);
        let peer = test_peer_id(2);
        let requester = test_peer_id(3);
        let transport = RecordingTransport::new(local);
        transport.set_connected_peer_ids(vec![peer, requester]);
        // No background tasks: the instrumentation is per-instance, but the
        // instance's OWN flusher shares this map and limiter — its 100 ms
        // ticks must not land in the exact-count asserts below (r4: keep
        // the measured window to the driven ticks only). The frame paths
        // under test all send inline or via spawned one-shot tasks, none
        // via the interval flusher.
        let pubsub = PlumtreePubSub::new_with_task_control(
            local,
            transport.clone(),
            test_signing_key(),
            false,
        );
        store_connected_peers_snapshot(
            pubsub.connected_peers_snapshot.as_ref(),
            Some(HashSet::from([peer, requester])),
        );
        assert!(
            !pubsub.egress_limiter.enabled(),
            "limiter is disabled by default"
        );
        let topic = TopicId::new([0x8a; 32]);
        pubsub.initialize_topic_peers(topic, vec![peer]).await;

        // Outbound frame path: a local publish fans EAGER out to the peer.
        pubsub
            .publish_local(topic, Bytes::from_static(b"zero-overhead"))
            .await
            .expect("publish");

        // Inbound IHAVE for an id we lack: sends an IWANT back.
        let unknown = [0x8b; 32];
        pubsub
            .handle_ihave(peer, topic, vec![unknown])
            .await
            .expect("ihave");

        // Inbound IWANT for our cached local publish: serves EAGER. Use an
        // independent connected requester so this assertion does not race
        // the spawned publish send's per-peer in-flight claim.
        let local_id = pubsub.calculate_msg_id(&topic, &Bytes::from_static(b"zero-overhead"));
        pubsub
            .handle_iwant(requester, topic, vec![local_id])
            .await
            .expect("iwant");

        assert_eq!(
            pubsub.egress_limiter.state_mutex_acquisitions_for_test(),
            0,
            "disabled limiter must cost zero state-mutex acquisitions on the frame paths"
        );
        // Scope the write_all count to the flush loop itself: setup paths
        // (publish fan-out, peer init) take their own locks; the invariant
        // under test is the flush's per-tick take count.
        pubsub
            .topics
            .reset_topic_contention_instrumentation_for_test();

        const FLUSH_TICKS: u64 = 3;
        // Consecutive ticks of one flusher: share the rotation state.
        let mut late_rotation = LateOfferRotation::default();
        for _ in 0..FLUSH_TICKS {
            PlumtreePubSub::<RecordingTransport>::flush_ihave_batches(
                &pubsub.topics,
                &pubsub.transport,
                &pubsub.signing_key,
                &pubsub.stage_stats,
                &pubsub.outbound_budgets,
                IhaveFlushEnv {
                    send_path: &pubsub.send_path_context(),
                    egress_limiter: &pubsub.egress_limiter,
                    late_rotation: &mut late_rotation,
                },
            )
            .await;
        }

        assert_eq!(
            pubsub
                .topics
                .contention
                .write_all_takes
                .load(Ordering::Relaxed),
            FLUSH_TICKS,
            "a disabled-limiter flush must take exactly one all-shard write_all per tick"
        );
        assert_eq!(
            pubsub.egress_limiter.state_mutex_acquisitions_for_test(),
            0,
            "flush ticks with a disabled limiter must not touch the limiter mutex either"
        );

        // Behaviour parity smoke: the disabled path still sends real frames
        // (EAGER publish, IWANT, EAGER serve) — zero overhead must not mean
        // zero work. Polled: some serve lanes hand off from spawned tasks.
        let sent = wait_for_sent_frames(&transport, 3).await;
        assert!(
            sent >= 3,
            "disabled limiter must not change what gets sent: {sent} frames"
        );
    }

    /// S3 invariants for the late-local-offer catch-up under a DISABLED
    /// limiter: the flush caps offers per tick, never scans the LRU under
    /// `write_all()`, scans under the narrow per-topic lock only for
    /// offers actually attempted, and (review r3, item 2) never retains
    /// more than the per-tick cap candidates while the all-shard
    /// `write_all()` is held — with 8 eligible candidates here, the r2
    /// collect-everything-then-truncate shape peaked at 8.
    ///
    /// Revert-fails: moving the batch selection back inside the write_all
    /// block trips `late_offer_scans_under_write_all` > 0; removing the
    /// per-tick cap makes the sent IHAVE count exceed the cap; restoring
    /// the r2 collect-everything selection trips the collected-peak
    /// assert below (8 > 4).
    #[tokio::test]
    async fn late_local_offer_flush_caps_per_tick_and_never_scans_under_write_all() {
        let local = test_peer_id(1);
        let transport = RecordingTransport::new(local);
        // No background tasks (r4): the instance's own flusher shares this
        // map, so its ticks must not add scans or IHAVEs to the exact-count
        // asserts below — the single driven flush below is the whole story.
        let pubsub = PlumtreePubSub::new_with_task_control(
            local,
            transport.clone(),
            test_signing_key(),
            false,
        );
        let topic = TopicId::new([0x8c; 32]);
        let catchup_peers: Vec<PeerId> = (2..(2 + MAX_LATE_LOCAL_OFFERS_PER_FLUSH as u8 + 4))
            .map(test_peer_id)
            .collect();
        transport.set_connected_peer_ids(catchup_peers.clone());
        store_connected_peers_snapshot(
            pubsub.connected_peers_snapshot.as_ref(),
            Some(catchup_peers.iter().copied().collect()),
        );
        pubsub.initialize_topic_peers(topic, vec![]).await;

        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics.entry(topic).or_insert_with(TopicState::new);
            for index in 0..3u8 {
                let mut id = [0x8d; 32];
                id[0] = index;
                state.cache_message(
                    id,
                    Bytes::from_static(b"local-catchup"),
                    test_header(topic, id),
                    true,
                );
            }
        }
        // Real flow: the membership refresh queues a catch-up offer per
        // newly connected peer because the topic holds local-origin ids.
        pubsub.set_topic_peers(topic, catchup_peers.clone()).await;

        PlumtreePubSub::<RecordingTransport>::flush_ihave_batches(
            &pubsub.topics,
            &pubsub.transport,
            &pubsub.signing_key,
            &pubsub.stage_stats,
            &pubsub.outbound_budgets,
            IhaveFlushEnv {
                send_path: &pubsub.send_path_context(),
                egress_limiter: &pubsub.egress_limiter,
                late_rotation: &mut LateOfferRotation::default(),
            },
        )
        .await;

        let total_ihave = transport
            .sent_frames()
            .into_iter()
            .filter(|(peer, _, _)| catchup_peers.contains(peer))
            .count();
        assert_eq!(
            total_ihave, MAX_LATE_LOCAL_OFFERS_PER_FLUSH,
            "one flush tick must page at most {MAX_LATE_LOCAL_OFFERS_PER_FLUSH} late offers (got {total_ihave})"
        );
        assert_eq!(
            pubsub
                .topics
                .contention
                .late_offer_scans_under_write_all
                .load(Ordering::Relaxed),
            0,
            "the late-offer LRU scan must never run under the all-shard write_all"
        );
        assert_eq!(
            pubsub
                .topics
                .contention
                .late_offer_lru_scans
                .load(Ordering::Relaxed),
            MAX_LATE_LOCAL_OFFERS_PER_FLUSH as u64,
            "exactly one narrow-lock scan per attempted offer"
        );
        assert!(
            pubsub
                .topics
                .contention
                .late_offer_max_collected
                .load(Ordering::Relaxed)
                <= MAX_LATE_LOCAL_OFFERS_PER_FLUSH as u64,
            "the under-write_all selection must retain at most \
             {MAX_LATE_LOCAL_OFFERS_PER_FLUSH} candidates (peak {})",
            pubsub
                .topics
                .contention
                .late_offer_max_collected
                .load(Ordering::Relaxed)
        );
    }

    /// Review r2, item 6 (+ r3 bounded rework): the per-tick late-offer
    /// cap must ROTATE across the candidate set. The shards and topics
    /// are walked in a fixed order and `late_local_offers` is a HashMap,
    /// so an always-take-the-first-N selector starves the tail of the
    /// order until the 60 s sweep. With five multi-page offers (1025 ids
    /// each — one page larger than a batch, so an attempted offer stays
    /// eligible next tick) and a cap of 4, tick 2 must start where tick 1
    /// stopped, not serve the same four topics again. Since r3 the
    /// rotation is a flusher-local key ring ranked incrementally under
    /// `write_all()` (never materializing the full sorted set); the
    /// rotation state is shared across the two driven ticks below, exactly
    /// as the flush task shares it across its interval ticks.
    ///
    /// Revert-fails: pinning the ring start at the head (fresh rotation
    /// every tick) makes tick 2 serve the same first four sorted topics →
    /// the tick-2 set assert fails.
    #[tokio::test]
    async fn late_offer_cap_rotates_across_ticks() {
        let local = test_peer_id(1);
        let transport = RecordingTransport::new(local);
        // No background tasks: the background flusher's own 100 ms ticks
        // would interleave frames with the two driven below.
        let pubsub = PlumtreePubSub::new_with_task_control(
            local,
            transport.clone(),
            test_signing_key(),
            false,
        );
        // Five topics, each with a DISTINCT peer so the frame's destination
        // identifies the topic; sorted by topic bytes below.
        let mut topics_peers: Vec<(TopicId, PeerId)> = (0..5u8)
            .map(|index| (TopicId::new([0xd0 + index; 32]), test_peer_id(index + 2)))
            .collect();
        topics_peers.sort_by_key(|(topic, _)| topic.to_bytes());
        transport.set_connected_peer_ids(topics_peers.iter().map(|(_, peer)| *peer).collect());
        store_connected_peers_snapshot(
            pubsub.connected_peers_snapshot.as_ref(),
            Some(topics_peers.iter().map(|(_, peer)| *peer).collect()),
        );

        for (topic, peer) in &topics_peers {
            pubsub.initialize_topic_peers(*topic, vec![*peer]).await;
            let mut topics = pubsub.topics.write_topic(topic).await;
            let state = topics.entry(*topic).or_insert_with(TopicState::new);
            for index in 0..=(MAX_IHAVE_BATCH_SIZE as u32) {
                let mut id = [0xd5; 32];
                id[..4].copy_from_slice(&index.to_le_bytes());
                state.cache_message(
                    id,
                    Bytes::from_static(b"rr-catchup"),
                    test_header(*topic, id),
                    true,
                );
            }
            // Capture the cutoff AFTER the inserts so every cached
            // `inserted_at <= cutoff` and is selectable.
            let now = Instant::now();
            state.late_local_offers.insert(
                *peer,
                LateLocalOffer {
                    cutoff: now,
                    cursor: None,
                    failures: 0,
                    next_attempt: None,
                },
            );
        }

        let served_topics = |transport: &RecordingTransport, topics_peers: &[(TopicId, PeerId)]| {
            let mut served: Vec<TopicId> = transport
                .sent_frames()
                .into_iter()
                .filter_map(|(peer, _, _)| {
                    topics_peers
                        .iter()
                        .find(|(_, candidate)| *candidate == peer)
                        .map(|(topic, _)| *topic)
                })
                .collect();
            served.sort_by_key(|topic| topic.to_bytes());
            served
        };

        // Tick 1: rotation starts at 0 → the first four sorted topics.
        let mut late_rotation = LateOfferRotation::default();
        PlumtreePubSub::<RecordingTransport>::flush_ihave_batches(
            &pubsub.topics,
            &pubsub.transport,
            &pubsub.signing_key,
            &pubsub.stage_stats,
            &pubsub.outbound_budgets,
            IhaveFlushEnv {
                send_path: &pubsub.send_path_context(),
                egress_limiter: &pubsub.egress_limiter,
                late_rotation: &mut late_rotation,
            },
        )
        .await;
        let tick1 = served_topics(&transport, &topics_peers);
        assert_eq!(
            tick1,
            topics_peers[..4]
                .iter()
                .map(|(t, _)| *t)
                .collect::<Vec<_>>(),
            "tick 1 serves the first four sorted topics"
        );

        // Tick 2: the ring start sits just past tick 1's last served
        // topic → rotation begins at index 4 of the (still) five eligible
        // offers: the fifth topic, then wrap to the first three.
        // Attempted offers stay eligible (multi-page), so a fixed-order
        // selector would repeat the same four here.
        PlumtreePubSub::<RecordingTransport>::flush_ihave_batches(
            &pubsub.topics,
            &pubsub.transport,
            &pubsub.signing_key,
            &pubsub.stage_stats,
            &pubsub.outbound_budgets,
            IhaveFlushEnv {
                send_path: &pubsub.send_path_context(),
                egress_limiter: &pubsub.egress_limiter,
                late_rotation: &mut late_rotation,
            },
        )
        .await;
        // Frames 4.. are tick 2's, chronologically (the transport
        // appends in send order); map them by peer WITHOUT re-sorting.
        let tick2: Vec<TopicId> = transport.sent_frames()[4..]
            .iter()
            .filter_map(|(peer, _, _)| {
                topics_peers
                    .iter()
                    .find(|(_, candidate)| candidate == peer)
                    .map(|(topic, _)| *topic)
            })
            .collect();

        let expected2: Vec<TopicId> = vec![
            topics_peers[4].0,
            topics_peers[0].0,
            topics_peers[1].0,
            topics_peers[2].0,
        ];
        assert_eq!(
            tick2, expected2,
            "tick 2 must rotate: fifth topic first, then wrap to the head"
        );
        assert_eq!(
            pubsub
                .topics
                .contention
                .late_offer_scans_under_write_all
                .load(Ordering::Relaxed),
            0,
            "rotation still never scans under the all-shard write_all"
        );
    }

    /// Review r2, item 7: `advance_late_local_offer` pages the LIVE offer
    /// forward regardless of the cutoff the batch was selected under. A
    /// re-queue between snapshot and outcome (new cutoff) must not turn
    /// the page-forward into a no-op — that re-signed the same page every
    /// tick.
    ///
    /// Revert-fail is compile-level: the reverted method requires a cutoff
    /// argument, so this call site cannot compile against it.
    #[test]
    fn late_offer_advance_applies_to_requeued_offer() {
        let topic = TopicId::new([0xd8; 32]);
        let peer = test_peer_id(2);
        let mut state = TopicState::new();
        state.cache_message(
            [0xd9; 32],
            Bytes::from_static(b"local"),
            test_header(topic, [0xd9; 32]),
            true,
        );
        // The LIVE offer carries a NEWER cutoff than any snapshot — the
        // shape a re-queue between snapshot and outcome produces.
        state.late_local_offers.insert(
            peer,
            LateLocalOffer {
                cutoff: Instant::now(),
                cursor: None,
                failures: 3,
                next_attempt: None,
            },
        );
        let cursor = (Instant::now(), [0xd9; 32]);
        state.advance_late_local_offer(peer, cursor);
        {
            let offer = state.late_local_offers.get(&peer).expect("offer kept");
            assert_eq!(offer.cursor, Some(cursor), "the live offer pages forward");
            assert_eq!(offer.failures, 0, "success clears the failure schedule");
            assert_eq!(offer.next_attempt, None);
        }
        state.backoff_late_local_offer(peer, cursor);
        {
            let offer = state.late_local_offers.get(&peer).expect("offer kept");
            assert_eq!(
                offer.cursor,
                Some(cursor),
                "backoff also pages the live offer forward"
            );
            assert_eq!(offer.failures, 1);
            assert!(offer.next_attempt.is_some());
        }
    }

    /// Review r2, item 5: an enabled→disabled reconfigure must not strand
    /// `deferred_eager_replies` in topic state until the limiter is
    /// re-enabled. The disabling `configure()` arms a residue flag; the
    /// FIRST disabled flush drains the custody and clears the flag, and
    /// the steady state stays zero-overhead afterwards.
    ///
    /// Revert-fails: without the drain, the entries survive the disabled
    /// flush and the emptiness assert fails.
    #[tokio::test]
    async fn disabling_reconfigure_drains_deferred_eager_replies() {
        let local = test_peer_id(1);
        let peer = test_peer_id(2);
        let transport = RecordingTransport::new(local);
        transport.set_connected_peer_ids(vec![peer]);
        let pubsub = PlumtreePubSub::new_with_task_control(
            local,
            transport.clone(),
            test_signing_key(),
            false,
        );
        let topic = TopicId::new([0xda; 32]);
        assert!(pubsub.configure_leaf_egress(Some(LeafEgressConfig {
            soft_bytes_per_second: 0,
            hard_bytes_per_second: 1024 * 1024,
            burst_bytes: 4 * 1024 * 1024,
            max_serialized_frame_bytes: 4 * 1024 * 1024,
            policy: BytePolicy::ObserveOnly,
        })));
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics.entry(topic).or_insert_with(TopicState::new);
            state.deferred_eager_replies.push(DeferredEagerReply {
                peer,
                msg_id: [0xdb; 32],
                requested_at: Instant::now(),
            });
        }

        // The disabling transition arms the residue flag.
        assert!(pubsub.configure_leaf_egress(None));
        assert!(!pubsub.egress_limiter.enabled());
        assert!(
            pubsub.egress_limiter.deferred_residue(),
            "an enabled→disabled transition must mark possible stranded custody"
        );

        // First disabled flush: regular work pass + ONE drain pass.
        let mut late_rotation = LateOfferRotation::default();
        PlumtreePubSub::<RecordingTransport>::flush_ihave_batches(
            &pubsub.topics,
            &pubsub.transport,
            &pubsub.signing_key,
            &pubsub.stage_stats,
            &pubsub.outbound_budgets,
            IhaveFlushEnv {
                send_path: &pubsub.send_path_context(),
                egress_limiter: &pubsub.egress_limiter,
                late_rotation: &mut late_rotation,
            },
        )
        .await;
        assert!(pubsub
            .topics
            .read_topic(&topic)
            .await
            .get(&topic)
            .expect("topic")
            .deferred_eager_replies
            .is_empty());
        assert!(
            !pubsub.egress_limiter.deferred_residue(),
            "the drain clears the flag"
        );

        // Steady state restored: one write_all per tick, no drain.
        pubsub
            .topics
            .reset_topic_contention_instrumentation_for_test();
        PlumtreePubSub::<RecordingTransport>::flush_ihave_batches(
            &pubsub.topics,
            &pubsub.transport,
            &pubsub.signing_key,
            &pubsub.stage_stats,
            &pubsub.outbound_budgets,
            IhaveFlushEnv {
                send_path: &pubsub.send_path_context(),
                egress_limiter: &pubsub.egress_limiter,
                late_rotation: &mut late_rotation,
            },
        )
        .await;
        assert_eq!(
            pubsub
                .topics
                .contention
                .write_all_takes
                .load(Ordering::Relaxed),
            1,
            "after the drain, a disabled flush takes exactly one write_all again"
        );
    }

    /// S3(c): a failed late-offer hand-off pages the cursor FORWARD and
    /// backs off — subsequent immediate ticks neither scan nor send for
    /// that offer, and the offer stays live (releasable once the backoff
    /// expires).
    ///
    /// Revert-fails: restoring cursor-advance-only-on-success makes the
    /// scan count grow with every extra tick below.
    #[tokio::test]
    async fn failed_late_offer_pages_forward_and_backs_off_not_tick_rate() {
        let local = test_peer_id(1);
        let peer = test_peer_id(2);
        let transport = FailingTransport::new(local, SendFailureMode::LiveIoError);
        transport.report_connected(vec![peer]);
        let pubsub = PlumtreePubSub::new_with_task_control(
            local,
            transport.clone(),
            test_signing_key(),
            false,
        );
        store_connected_peers_snapshot(
            pubsub.connected_peers_snapshot.as_ref(),
            Some(HashSet::from([peer])),
        );
        let topic = TopicId::new([0x8e; 32]);
        pubsub.initialize_topic_peers(topic, vec![peer]).await;

        // More local-origin ids than one IHAVE batch, so a FAILED first
        // page still leaves a second page to attempt after the backoff
        // (the cursor pages forward past the failed ids by design).
        let ids: Vec<MessageIdType> = (0..=(MAX_IHAVE_BATCH_SIZE as u32))
            .map(|index| {
                let mut id = [0x8f; 32];
                id[..4].copy_from_slice(&index.to_le_bytes());
                id
            })
            .collect();
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics.entry(topic).or_insert_with(TopicState::new);
            for id in &ids {
                state.cache_message(
                    *id,
                    Bytes::from_static(b"local-catchup"),
                    test_header(topic, *id),
                    true,
                );
            }
            // Capture the cutoff AFTER the inserts so every cached
            // `inserted_at <= cutoff` and is selectable.
            let now = Instant::now();
            state.late_local_offers.insert(
                peer,
                LateLocalOffer {
                    cutoff: now,
                    cursor: None,
                    failures: 0,
                    next_attempt: None,
                },
            );
        }

        let mut late_rotation = LateOfferRotation::default();
        for _ in 0..5 {
            PlumtreePubSub::<FailingTransport>::flush_ihave_batches(
                &pubsub.topics,
                &pubsub.transport,
                &pubsub.signing_key,
                &pubsub.stage_stats,
                &pubsub.outbound_budgets,
                IhaveFlushEnv {
                    send_path: &pubsub.send_path_context(),
                    egress_limiter: &pubsub.egress_limiter,
                    late_rotation: &mut late_rotation,
                },
            )
            .await;
        }

        assert_eq!(
            transport.send_attempts(),
            1,
            "only the first tick may attempt the offer; the backoff must suppress the rest"
        );
        assert_eq!(
            pubsub
                .topics
                .contention
                .late_offer_lru_scans
                .load(Ordering::Relaxed),
            1,
            "backoff blocks even the rescan, not just the send"
        );
        {
            let topics = pubsub.topics.read_topic(&topic).await;
            let offer = topics
                .get(&topic)
                .expect("topic")
                .late_local_offers
                .get(&peer)
                .expect("offer survives a failed send under backoff");
            assert_eq!(offer.failures, 1);
            assert!(
                offer.next_attempt.is_some_and(|t| t > Instant::now()),
                "a retry backoff must be outstanding"
            );
            assert!(
                offer.cursor.is_some(),
                "a failed hand-off must still page the cursor forward"
            );
        }

        // Expiring the backoff re-enables exactly one more attempt.
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics.get_mut(&topic).expect("topic");
            let offer = state.late_local_offers.get_mut(&peer).expect("offer");
            offer.next_attempt = Some(Instant::now() - Duration::from_secs(1));
        }
        PlumtreePubSub::<FailingTransport>::flush_ihave_batches(
            &pubsub.topics,
            &pubsub.transport,
            &pubsub.signing_key,
            &pubsub.stage_stats,
            &pubsub.outbound_budgets,
            IhaveFlushEnv {
                send_path: &pubsub.send_path_context(),
                egress_limiter: &pubsub.egress_limiter,
                late_rotation: &mut late_rotation,
            },
        )
        .await;
        assert_eq!(
            transport.send_attempts(),
            2,
            "one attempt per backoff expiry"
        );
    }

    /// S5: a failed IWANT keeps its claim under backoff. Immediate
    /// re-advertisements cannot re-request the id; an expired backoff can.
    ///
    /// Revert-fails: restoring release-on-failure drops the claim (the
    /// contains-key assertion fails); removing the backoff check makes the
    /// attempt count equal the advertisement count.
    #[tokio::test]
    async fn failed_iwant_keeps_claim_under_backoff_not_arrival_rate() {
        let local = test_peer_id(1);
        let peer = test_peer_id(2);
        // The 50 ms send delay separates "request time" from "failure
        // time": a failure that refreshed `requested_at` would stamp it
        // ≥50 ms after the request (asserted below), re-arming the 60 s
        // age sweep on every failure — an unbounded claim lifetime
        // (review r2, MUST 1).
        let transport = FailingTransport::new_delayed(
            local,
            SendFailureMode::LiveIoError,
            Duration::from_millis(50),
        );
        transport.report_connected(vec![peer]);
        let pubsub = PlumtreePubSub::new_with_task_control(
            local,
            transport.clone(),
            test_signing_key(),
            false,
        );
        let topic = TopicId::new([0x90; 32]);
        pubsub.initialize_topic_peers(topic, vec![peer]).await;
        let id = [0x91; 32];

        // First advertisement: one IWANT attempt, which fails at the transport.
        let request_started = Instant::now();
        let _ = pubsub.handle_ihave(peer, topic, vec![id]).await;
        assert_eq!(transport.send_attempts(), 1);
        let first_requested_at = {
            let topics = pubsub.topics.read_topic(&topic).await;
            let entry = topics
                .get(&topic)
                .expect("topic")
                .outstanding_iwants
                .get(&id)
                .expect("a failed IWANT must keep its claim");
            assert_eq!(entry.peer, peer);
            assert_eq!(entry.failures, 1);
            assert!(
                entry.retry_not_before.is_some_and(|t| t > Instant::now()),
                "a retry backoff must be recorded"
            );
            assert!(
                entry.requested_at < request_started + Duration::from_millis(40),
                "requested_at must stay at REQUEST time, not be refreshed to                  failure time (the delayed send fails at ≥50 ms) — the 60 s                  sweep must bound the claim from the FIRST request"
            );
            entry.requested_at
        };

        // Re-advertise immediately, many times: the failing peer's backoff
        // suppresses every re-request (this is the 0.5.83 regression — the
        // release let each arrival send a fresh IWANT).
        for _ in 0..25 {
            let _ = pubsub.handle_ihave(peer, topic, vec![id]).await;
        }
        assert_eq!(
            transport.send_attempts(),
            1,
            "repeated advertisements inside the backoff window must not re-send"
        );

        // Expire the backoff: the next advertisement may re-request once.
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics.get_mut(&topic).expect("topic");
            let entry = state.outstanding_iwants.get_mut(&id).expect("claim kept");
            entry.retry_not_before = Some(Instant::now() - Duration::from_secs(1));
        }
        let _ = pubsub.handle_ihave(peer, topic, vec![id]).await;
        assert_eq!(transport.send_attempts(), 2);
        {
            let topics = pubsub.topics.read_topic(&topic).await;
            let entry = topics
                .get(&topic)
                .expect("topic")
                .outstanding_iwants
                .get(&id)
                .expect("claim survives the retried failure");
            assert_eq!(entry.failures, 2, "failures accumulate for the schedule");
            // The retry re-created the claim (a genuine new request, fresh
            // requested_at by design); the first-attempt assert above is
            // what pins "failures never refresh requested_at".
            let _ = first_requested_at;
        }
    }

    /// S5 (review r2, MUST 1): the retry backoff is keyed on the FAILING
    /// peer. Peer A's failed IWANT suppresses re-requests only from A; a
    /// DIFFERENT peer advertising the same id is asked immediately — with
    /// 15 s Critical DM deadlines, suppressing a healthy source for up to
    /// 16 s is exactly the failure mode this PR removes.
    ///
    /// Revert-fails: restoring per-id suppression (dropping the
    /// `entry.peer == from` scope) keeps B suppressed → attempts stay 1.
    #[tokio::test]
    async fn different_advertiser_asked_immediately_after_peer_failure() {
        let local = test_peer_id(1);
        let failing_peer = test_peer_id(2);
        let other_peer = test_peer_id(3);
        let transport = FailingTransport::new(local, SendFailureMode::LiveIoError);
        transport.report_connected(vec![failing_peer, other_peer]);
        let pubsub = PlumtreePubSub::new_with_task_control(
            local,
            transport.clone(),
            test_signing_key(),
            false,
        );
        let topic = TopicId::new([0x93; 32]);
        pubsub
            .initialize_topic_peers(topic, vec![failing_peer, other_peer])
            .await;
        let id = [0x94; 32];

        // A advertises; our IWANT to A fails at the transport.
        let _ = pubsub.handle_ihave(failing_peer, topic, vec![id]).await;
        assert_eq!(transport.send_attempts(), 1);

        // B advertises the same id 200 ms of loop time later (immediately
        // here): B is a different, untried source and MUST be asked at
        // once — not held behind A's backoff.
        let _ = pubsub.handle_ihave(other_peer, topic, vec![id]).await;
        assert_eq!(
            transport.send_attempts(),
            2,
            "a different advertiser must be asked immediately after the \
             failing peer's backoff was armed"
        );
        {
            let topics = pubsub.topics.read_topic(&topic).await;
            let entry = topics
                .get(&topic)
                .expect("topic")
                .outstanding_iwants
                .get(&id)
                .expect("B's request holds the claim now");
            assert_eq!(entry.peer, other_peer);
            // The transport fails for every peer, so B's own attempt also
            // records failures=1 — the point is that B was ASKED (the
            // attempts assert above), with a schedule starting from B's
            // own first failure rather than inheriting A's.
        }

        // A re-advertising while the claim belongs to B: allowed only
        // because B's claim is in a failed state (B's send also failed —
        // the transport fails for every peer), so A is again a fresh,
        // untried source. While B's claim would have been HEALTHY, A's
        // IHAVE is suppressed — see the r3 test below.
    }

    /// Review r3, MUST 1: a HEALTHY claim is never stolen. A is asked for
    /// an id and the send SUCCEEDS; B then advertises the same id. B must
    /// NOT be asked — the id already has an in-flight request — otherwise
    /// every multi-advertiser id costs one duplicate IWANT plus a full
    /// payload reply (and an MLDSA verify) per extra advertiser.
    ///
    /// Revert-fails: restoring the unconditional takeover (removing the
    /// `retry_not_before.is_none()` healthy-claim guard) sends B the
    /// duplicate IWANT → the zero assert below reads 1.
    #[tokio::test]
    async fn healthy_iwant_claim_not_stolen_by_second_advertiser() {
        let local = test_peer_id(1);
        let transport = RecordingTransport::new(local);
        let topic = TopicId::new([0x95; 32]);
        let peer_a = test_peer_id(2);
        let peer_b = test_peer_id(3);
        transport.set_connected_peer_ids(vec![peer_a, peer_b]);
        let pubsub = PlumtreePubSub::new_with_task_control(
            local,
            transport.clone(),
            test_signing_key(),
            false,
        );
        let id = [0x96; 32];

        // A advertises; the IWANT to A is sent and SUCCEEDS.
        pubsub
            .handle_ihave(peer_a, topic, vec![id])
            .await
            .expect("IHAVE handling from A");
        assert_eq!(
            transport.send_count_to(peer_a),
            1,
            "A is asked for the id exactly once"
        );

        // B advertises the same id while A's claim is healthy (send
        // handed off, no failure, no backoff): the claim must NOT be
        // taken over — B would be sent a duplicate IWANT for an id that
        // is already in flight.
        pubsub
            .handle_ihave(peer_b, topic, vec![id])
            .await
            .expect("IHAVE handling from B");
        assert_eq!(
            transport.send_count_to(peer_b),
            0,
            "a healthy claim must not be stolen: 0 IWANTs to B, expected 0"
        );
        {
            let topics = pubsub.topics.read_topic(&topic).await;
            let entry = topics
                .get(&topic)
                .expect("topic")
                .outstanding_iwants
                .get(&id)
                .expect("A keeps the claim");
            assert_eq!(entry.peer, peer_a, "the claim still belongs to A");
            assert_eq!(entry.failures, 0, "A has not failed");
            assert_eq!(
                entry.retry_not_before, None,
                "the claim is healthy, not in a failed state"
            );
        }
    }

    /// S5 bound: the exponential schedule (1, 2, 4, 8, capped 16 s)
    /// permits at most 8 attempts in any 60 s window — versus up to ~600
    /// at the 100 ms tick rate the unbounded retry reached.
    #[test]
    fn iwant_retry_backoff_schedule_bounds_sixty_second_window() {
        let mut next = Duration::ZERO;
        let mut attempts = 0;
        while next <= Duration::from_secs(60) {
            attempts += 1;
            next += iwant_retry_backoff(u8::try_from(attempts).expect("u8"));
        }
        assert!(
            attempts <= 8,
            "schedule must bound a 60 s window to ≤8 attempts, got {attempts}"
        );
        assert_eq!(iwant_retry_backoff(1), Duration::from_secs(1));
        assert_eq!(iwant_retry_backoff(5), Duration::from_secs(16));
        assert_eq!(iwant_retry_backoff(200), Duration::from_secs(16), "capped");
    }

    /// S3(d): the O(1) live-local-origin counter must agree with a
    /// brute-force LRU scan across every mutation class — insertion,
    /// replacement, drop-marking, age expiry, byte eviction, and count
    /// eviction. A missed decrement site drifts the counter and fails here.
    #[test]
    fn live_local_origin_counter_matches_bruteforce_scan() {
        fn brute_force(cache: &BoundedMessageCache) -> usize {
            cache
                .lru
                .iter()
                .filter(|(_, entry)| entry.message.local_origin && !entry.message.dropped)
                .count()
        }
        fn check(cache: &BoundedMessageCache, stage: &str) {
            assert_eq!(
                cache.live_local_origin,
                brute_force(cache),
                "counter drift after {stage}"
            );
        }

        let topic = TopicId::new([0x92; 32]);
        let now = Instant::now();
        let local_cached = |id: MessageIdType| CachedMessage {
            payload: Bytes::from(vec![0u8; 256]),
            header: test_header(topic, id),
            dropped: false,
            local_origin: true,
            inner_proof: None,
        };
        let relayed_cached = |id: MessageIdType| CachedMessage {
            payload: Bytes::from(vec![0u8; 256]),
            header: test_header(topic, id),
            dropped: false,
            local_origin: false,
            inner_proof: None,
        };
        let entry_bytes = estimate_message_bytes(&local_cached([0; 32]));
        let mut cache = BoundedMessageCache::new(
            NonZeroUsize::new(8).expect("nonzero"),
            entry_bytes * 3,
            Duration::from_secs(60),
        );

        let local_a = [0xa1; 32];
        let local_b = [0xa2; 32];
        let relayed = [0xa3; 32];
        assert!(cache.insert_at(local_a, local_cached(local_a), now));
        check(&cache, "local insert");
        assert!(cache.insert_at(relayed, relayed_cached(relayed), now));
        check(&cache, "relayed insert");
        assert_eq!(cache.live_local_origin, 1);

        // Drop-marking a local entry decrements.
        assert!(cache.mark_dropped(&local_a));
        check(&cache, "drop-mark");
        assert_eq!(cache.live_local_origin, 0);

        // Re-inserting a live local entry over a dropped one counts once.
        assert!(cache.insert_at(local_a, local_cached(local_a), now));
        check(&cache, "replacement");
        assert_eq!(cache.live_local_origin, 1);

        // Age expiry decrements.
        assert!(cache.insert_at(
            local_b,
            local_cached(local_b),
            now - Duration::from_secs(61)
        ));
        check(&cache, "stale insert");
        cache.prune_expired_at(now);
        check(&cache, "age expiry");
        assert_eq!(cache.live_local_origin, 1);

        // Byte eviction decrements: three fresh local entries exceed the
        // byte cap and evict the older ones.
        for index in 0..4u8 {
            let id = [0xb0 + index; 32];
            assert!(cache.insert_at(id, local_cached(id), now));
            check(&cache, "byte-pressure insert {index}");
        }
        assert!(cache.has_live_local_origin());

        // Count eviction decrements: tiny count cap.
        let mut tiny = BoundedMessageCache::new(
            NonZeroUsize::new(2).expect("nonzero"),
            usize::MAX,
            Duration::from_secs(60),
        );
        for index in 0..4u8 {
            let id = [0xc0 + index; 32];
            assert!(tiny.insert_at(id, local_cached(id), now));
            check(&tiny, "count-pressure insert {index}");
        }
    }

    /// WHY: two pulls for the same delivery share one custody entry, so a
    /// requester that retries cannot multiply the retained replies. The
    /// authority-ordering half of this test went away with
    /// `DeferredEagerReply::local_origin_only`: a local-origin reply is
    /// protected from shedding and so never reaches custody, leaving nothing
    /// for the two orderings to merge.
    #[test]
    fn deferred_eager_reply_deduplicates_repeat_requests() {
        let peer = test_peer_id(2);
        let topic = TopicId::new([0x8f; 32]);
        let msg_id = [0x90; 32];
        let now = Instant::now();
        let mut state = TopicState::new();
        state.cache_message(
            msg_id,
            Bytes::from_static(b"relayed"),
            test_header(topic, msg_id),
            false,
        );
        for _ in 0..2 {
            assert!(state.retain_deferred_eager_reply(peer, msg_id, now));
        }
        assert_eq!(state.deferred_eager_replies.len(), 1);
    }

    #[test]
    fn deferred_eager_reply_custody_is_bounded_and_cache_authorized() {
        let peer = test_peer_id(2);
        let topic = TopicId::new([0x91; 32]);
        let now = Instant::now();
        let mut state = TopicState::with_cache_config(PubSubCacheConfig {
            max_messages_per_topic: NonZeroUsize::new(MAX_DEFERRED_EAGER_REPLIES + 2)
                .expect("nonzero"),
            max_bytes_per_topic: (b"overflow".len()
                + MESSAGE_HEADER_OVERHEAD_BYTES
                + MESSAGE_CRYPTO_OVERHEAD_BYTES)
                * (MAX_DEFERRED_EAGER_REPLIES + 2),
            max_age: Duration::from_secs(1),
        });
        for index in 0..MAX_DEFERRED_EAGER_REPLIES {
            let mut id = [0u8; 32];
            id[..8].copy_from_slice(&u64::try_from(index).expect("bounded index").to_le_bytes());
            state.cache_message(
                id,
                Bytes::from_static(b"local"),
                test_header(topic, id),
                true,
            );
            assert!(state.retain_deferred_eager_reply(peer, id, now));
        }
        let overflow = [0xfe; 32];
        state.cache_message(
            overflow,
            Bytes::from_static(b"overflow"),
            test_header(topic, overflow),
            true,
        );
        assert_eq!(state.message_cache.len(), MAX_DEFERRED_EAGER_REPLIES + 1);
        assert!(!state.retain_deferred_eager_reply(peer, overflow, now));
        assert_eq!(
            state.deferred_eager_replies.len(),
            MAX_DEFERRED_EAGER_REPLIES
        );

        state.prune_deferred_eager_replies(now + Duration::from_millis(999));
        assert_eq!(
            state.deferred_eager_replies.len(),
            MAX_DEFERRED_EAGER_REPLIES
        );
        state.prune_deferred_eager_replies(now + Duration::from_millis(1_001));
        assert!(state.deferred_eager_replies.is_empty());

        // A relay entry whose cache message is still live is retained; pruning
        // is authorized by the cache, not by provenance. (This previously
        // asserted the opposite for a `local_origin_only` entry — that filter
        // went away with the flag, since a local-origin reply is protected and
        // never reaches custody.)
        let remote = [0xfd; 32];
        state.cache_message(
            remote,
            Bytes::from_static(b"remote"),
            test_header(topic, remote),
            false,
        );
        assert!(state.retain_deferred_eager_reply(peer, remote, Instant::now()));
        state.prune_deferred_eager_replies(Instant::now());
        assert_eq!(
            state.deferred_eager_replies.len(),
            1,
            "a live relay cache entry keeps its custody"
        );
    }

    #[tokio::test]
    /// The rejected classes are *cache* invalidity — dropped and expired — and
    /// a disconnected peer. A remote-origin entry used to be a third class,
    /// rejected by the `local_origin_only` serve-side filter; that filter went
    /// away with the flag, and a live relay entry is now exactly what this
    /// custody legitimately serves.
    async fn deferred_eager_reply_flush_rejects_invalid_cache_and_disconnects() {
        let local = test_peer_id(1);
        let peer = test_peer_id(2);
        let topic = TopicId::new([0x92; 32]);
        let transport = RecordingTransport::new(local);
        transport.set_connected_peer_ids(vec![peer]);
        let pubsub = PlumtreePubSub::new_with_task_control(
            local,
            transport.clone(),
            test_signing_key(),
            false,
        );
        // Deferred replies only exist while the limiter is enabled (a
        // `Deferred` outcome requires it); the disabled flush now skips the
        // deferred pass entirely (relay overhead invariant), so seed the
        // state under ObserveOnly — the realistic producer of this custody.
        assert!(pubsub.configure_leaf_egress(Some(LeafEgressConfig {
            soft_bytes_per_second: 0,
            hard_bytes_per_second: 1024 * 1024,
            burst_bytes: 4 * 1024 * 1024,
            max_serialized_frame_bytes: 4 * 1024 * 1024,
            policy: BytePolicy::ObserveOnly,
        })));
        let now = Instant::now();
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics.entry(topic).or_insert_with(|| {
                TopicState::with_cache_config(PubSubCacheConfig {
                    max_messages_per_topic: NonZeroUsize::new(8).expect("nonzero"),
                    max_bytes_per_topic: 64 * 1024,
                    max_age: Duration::from_secs(1),
                })
            });
            let dropped = [0x93; 32];
            state.cache_message(
                dropped,
                Bytes::from_static(b"dropped"),
                test_header(topic, dropped),
                true,
            );
            state.mark_message_dropped(&dropped);
            let expired = [0x95; 32];
            state.message_cache.insert_at(
                expired,
                CachedMessage {
                    payload: Bytes::from_static(b"expired"),
                    header: test_header(topic, expired),
                    dropped: false,
                    local_origin: true,
                    inner_proof: None,
                },
                now - Duration::from_secs(2),
            );
            state.deferred_eager_replies.extend([
                DeferredEagerReply {
                    peer,
                    msg_id: dropped,
                    requested_at: now,
                },
                DeferredEagerReply {
                    peer,
                    msg_id: expired,
                    requested_at: now,
                },
            ]);
        }
        PlumtreePubSub::<RecordingTransport>::flush_ihave_batches(
            &pubsub.topics,
            &pubsub.transport,
            &pubsub.signing_key,
            &pubsub.stage_stats,
            &pubsub.outbound_budgets,
            IhaveFlushEnv {
                send_path: &pubsub.send_path_context(),
                egress_limiter: &pubsub.egress_limiter,
                late_rotation: &mut LateOfferRotation::default(),
            },
        )
        .await;
        assert!(transport.sent_frames().is_empty());
        assert!(pubsub
            .topics
            .read_topic(&topic)
            .await
            .get(&topic)
            .expect("topic")
            .deferred_eager_replies
            .is_empty());

        let live = [0x96; 32];
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics.get_mut(&topic).expect("topic");
            state.cache_message(
                live,
                Bytes::from_static(b"live"),
                test_header(topic, live),
                true,
            );
            assert!(state.retain_deferred_eager_reply(peer, live, Instant::now()));
        }
        pubsub.set_topic_peers(topic, vec![peer]).await;
        pubsub.set_topic_peers(topic, Vec::new()).await;
        assert!(pubsub
            .topics
            .read_topic(&topic)
            .await
            .get(&topic)
            .expect("topic")
            .deferred_eager_replies
            .is_empty());
    }

    #[tokio::test]
    async fn deferred_eager_reply_success_marks_stranded_pull_served() {
        let local = test_peer_id(1);
        let peer = test_peer_id(2);
        let topic = TopicId::new([0x97; 32]);
        let transport = RecordingTransport::new(local);
        transport.set_connected_peer_ids(vec![peer]);
        let pubsub = PlumtreePubSub::new_with_task_control(
            local,
            transport.clone(),
            test_signing_key(),
            false,
        );
        // Deferred custody requires an enabled limiter (see the sibling
        // test above); the disabled flush skips the deferred pass.
        assert!(pubsub.configure_leaf_egress(Some(LeafEgressConfig {
            soft_bytes_per_second: 0,
            hard_bytes_per_second: 1024 * 1024,
            burst_bytes: 4 * 1024 * 1024,
            max_serialized_frame_bytes: 4 * 1024 * 1024,
            policy: BytePolicy::ObserveOnly,
        })));
        let payload = Bytes::from_static(b"stranded-pull-reply");
        let msg_id = pubsub.calculate_msg_id(&topic, &payload);
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics
                .entry(topic)
                .or_insert_with(|| pubsub.new_topic_state());
            state.cache_message(msg_id, payload, test_header(topic, msg_id), true);
            state.queue_stranded_ihave(msg_id, &[peer]);
            assert!(state.retain_deferred_eager_reply(peer, msg_id, Instant::now()));
        }

        PlumtreePubSub::<RecordingTransport>::flush_ihave_batches(
            &pubsub.topics,
            &pubsub.transport,
            &pubsub.signing_key,
            &pubsub.stage_stats,
            &pubsub.outbound_budgets,
            IhaveFlushEnv {
                send_path: &pubsub.send_path_context(),
                egress_limiter: &pubsub.egress_limiter,
                late_rotation: &mut LateOfferRotation::default(),
            },
        )
        .await;
        assert_eq!(
            transport
                .sent_frames_of_kind_to(peer, MessageKind::Eager)
                .len(),
            1
        );
        let topics = pubsub.topics.read_topic(&topic).await;
        let state = topics.get(&topic).expect("topic");
        assert!(state.deferred_eager_replies.is_empty());
        assert!(
            state.stranded_ihave_targets_for(&[msg_id]).is_empty(),
            "a successful pull reply excludes the peer from later stranded EAGER retry"
        );
    }

    #[tokio::test]
    async fn late_local_offer_survives_leaf_budget_deferral_then_sends_once() {
        let local = test_peer_id(1);
        let peer = test_peer_id(2);
        let topic = TopicId::new([0x84; 32]);
        let transport = RecordingTransport::new(local);
        transport.set_connected_peer_ids(vec![peer]);
        let pubsub = PlumtreePubSub::new_with_task_control(
            local,
            transport.clone(),
            test_signing_key(),
            false,
        );
        let payload = Bytes::from_static(b"deferred-late-history");
        let id = pubsub.calculate_msg_id(&topic, &payload);
        pubsub
            .publish_local(topic, payload)
            .await
            .expect("cache local history");
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            topics.get_mut(&topic).expect("topic").pending_ihave.clear();
        }
        pubsub.set_topic_peers(topic, vec![peer]).await;

        let ihave_payload: Bytes = postcard::to_stdvec(&vec![id]).expect("ids").into();
        let mut header = MessageHeader {
            version: 1,
            payload_hash: None,
            topic,
            msg_id: id,
            kind: MessageKind::IHave,
            hop: 0,
            ttl: 10,
        };
        header.seal_payload_hash(Some(ihave_payload.as_ref()));
        let frame_len = postcard::to_stdvec(&GossipMessage {
            signature: pubsub.sign_message(&header),
            public_key: pubsub.signing_key.public_key().to_vec(),
            header,
            payload: Some(ihave_payload),
        })
        .expect("IHAVE frame")
        .len();
        assert!(pubsub.configure_leaf_egress(Some(LeafEgressConfig {
            soft_bytes_per_second: 0,
            hard_bytes_per_second: u64::try_from(frame_len).expect("frame size"),
            burst_bytes: u64::try_from(frame_len).expect("frame size"),
            max_serialized_frame_bytes: frame_len,
            policy: BytePolicy::ShedNormal,
        })));
        let drain = PlumtreePubSub::<RecordingTransport>::recovery_intent_key(
            topic,
            peer,
            "EAGER",
            b"drain-late-offer",
        );
        let _competing_charge = pubsub
            .egress_limiter
            .reserve_critical_eager(drain, frame_len, Duration::from_secs(1))
            .await
            .expect("competing Critical EAGER consumes the bounded burst");

        let mut late_rotation = LateOfferRotation::default();
        PlumtreePubSub::<RecordingTransport>::flush_ihave_batches(
            &pubsub.topics,
            &pubsub.transport,
            &pubsub.signing_key,
            &pubsub.stage_stats,
            &pubsub.outbound_budgets,
            IhaveFlushEnv {
                send_path: &pubsub.send_path_context(),
                egress_limiter: &pubsub.egress_limiter,
                late_rotation: &mut late_rotation,
            },
        )
        .await;
        // #504 opt-in policy: a late-local-offer page advertises only messages
        // this node authored (`late_local_offer_batch` filters on
        // `local_origin`), so the byte budget may not shed it even with the
        // burst consumed. This stage used to assert a deferral here and a send
        // on the next flush; the surviving subject is that the offer is sent
        // exactly once and its cursor then completes.
        assert_eq!(
            transport
                .sent_frames_of_kind_to(peer, MessageKind::IHave)
                .len(),
            1,
            "a protected local-origin offer is sent despite the exhausted burst"
        );
        let purpose = pubsub
            .leaf_egress_snapshot()
            .by_topic_and_purpose
            .into_iter()
            .find(|row| row.topic == topic.to_bytes() && row.purpose == "IHAVE")
            .expect("IHAVE accounting");
        assert_eq!(
            purpose.sent_bytes,
            u64::try_from(frame_len).expect("frame size"),
            "charged exactly once"
        );
        assert_eq!(
            pubsub.leaf_egress_snapshot().invariant_violations,
            0,
            "the protected offer carries a real reservation"
        );

        PlumtreePubSub::<RecordingTransport>::flush_ihave_batches(
            &pubsub.topics,
            &pubsub.transport,
            &pubsub.signing_key,
            &pubsub.stage_stats,
            &pubsub.outbound_budgets,
            IhaveFlushEnv {
                send_path: &pubsub.send_path_context(),
                egress_limiter: &pubsub.egress_limiter,
                late_rotation: &mut late_rotation,
            },
        )
        .await;
        assert_eq!(
            transport
                .sent_frames_of_kind_to(peer, MessageKind::IHave)
                .len(),
            1
        );
    }

    #[tokio::test]
    async fn local_origin_iwant_rejects_non_iwant_and_malformed_frames() {
        let local = test_peer_id(1);
        let requester = test_peer_id(2);
        let topic = TopicId::new([0x75; 32]);
        let transport = RecordingTransport::new(local);
        let pubsub = PlumtreePubSub::new(local, transport, test_signing_key());
        let ids: Bytes = postcard::to_stdvec(&vec![[0x76; 32]]).expect("ids").into();
        assert!(pubsub
            .handle_local_origin_iwant(
                requester,
                signed_control_frame(&pubsub, topic, MessageKind::IHave, ids),
            )
            .await
            .is_err());
        let mut trailing = signed_control_frame(
            &pubsub,
            topic,
            MessageKind::IWant,
            postcard::to_stdvec(&vec![[0x76; 32]]).expect("ids").into(),
        )
        .to_vec();
        trailing.push(0);
        assert!(pubsub
            .handle_local_origin_iwant(requester, trailing.into())
            .await
            .is_err());
        assert!(pubsub
            .handle_local_origin_iwant(requester, Bytes::from_static(b"malformed"))
            .await
            .is_err());
        assert!(pubsub
            .handle_local_origin_iwant(
                requester,
                signed_control_frame(
                    &pubsub,
                    topic,
                    MessageKind::IWant,
                    Bytes::from_static(b"bad-id-vector"),
                ),
            )
            .await
            .is_err());
        let valid_payload: Bytes = postcard::to_stdvec(&vec![[0x76; 32]]).expect("ids").into();
        let valid = signed_control_frame(&pubsub, topic, MessageKind::IWant, valid_payload);
        let mut invalid: GossipMessage = postcard::from_bytes(&valid).expect("signed frame");
        invalid.signature[0] ^= 1;
        assert!(pubsub
            .handle_local_origin_iwant(
                requester,
                postcard::to_stdvec(&invalid)
                    .expect("invalid signature frame")
                    .into(),
            )
            .await
            .is_err());
    }

    #[test]
    fn local_origin_custody_survives_echo_but_never_elevates_remote_cache() {
        let topic = TopicId::new([0x77; 32]);
        let id = [0x78; 32];
        let mut state = TopicState::new();
        state.cache_message(
            id,
            Bytes::from_static(b"remote-first"),
            test_header(topic, id),
            false,
        );
        assert!(!state.get_message(&id).expect("remote entry").local_origin);
        state.cache_message(
            id,
            Bytes::from_static(b"local"),
            test_header(topic, id),
            true,
        );
        let local_proof = compat::VerifiedInner {
            author: test_peer_id(3),
            digest: [0x79; 32],
            revision: 7,
        };
        state.set_inner_proof(id, Some(local_proof.clone()));
        let inbound_proof = compat::VerifiedInner {
            author: test_peer_id(4),
            digest: [0x7a; 32],
            revision: 8,
        };
        if state.cache_message(
            id,
            Bytes::from_static(b"wire-echo"),
            test_header(topic, id),
            false,
        ) {
            state.set_inner_proof(id, Some(inbound_proof));
        }
        let cached = state.get_message(&id).expect("promoted local entry");
        assert!(cached.local_origin);
        assert_eq!(cached.payload, Bytes::from_static(b"local"));
        assert_eq!(cached.inner_proof, Some(local_proof));
    }

    #[test]
    fn local_origin_query_excludes_dropped_and_expired_entries() {
        let topic = TopicId::new([0x79; 32]);
        let dropped_id = [0x7a; 32];
        let expired_id = [0x7b; 32];
        let mut state = TopicState::with_cache_config(PubSubCacheConfig {
            max_messages_per_topic: NonZeroUsize::new(4).expect("nonzero"),
            max_bytes_per_topic: 64 * 1024,
            max_age: Duration::from_secs(1),
        });
        state.cache_message(
            dropped_id,
            Bytes::from_static(b"dropped"),
            test_header(topic, dropped_id),
            true,
        );
        state.mark_message_dropped(&dropped_id);
        state.message_cache.insert_at(
            expired_id,
            CachedMessage {
                payload: Bytes::from_static(b"expired"),
                header: test_header(topic, expired_id),
                dropped: false,
                local_origin: true,
                inner_proof: None,
            },
            Instant::now() - Duration::from_secs(2),
        );
        // The counter is O(1); age-exact answers prune first, exactly as
        // the production callers (`queue_late_local_offer`,
        // `locally_originated_cached_topic_ids`) do.
        state.message_cache.prune_expired();
        assert!(!state.has_live_local_origin());
        assert!(!state.message_cache.contains(&expired_id));
    }

    #[tokio::test]
    async fn leaf_recovery_reservation_reaches_real_transport_send_seam() {
        let local = test_peer_id(1);
        let remote = test_peer_id(2);
        let topic = TopicId::new([9u8; 32]);
        let transport = RecordingTransport::new(local);
        transport.set_connected_peer_ids(vec![remote]);
        let pubsub = PlumtreePubSub::new(local, transport.clone(), test_signing_key());
        pubsub.initialize_topic_peers(topic, vec![remote]).await;
        assert!(pubsub.configure_leaf_egress(Some(LeafEgressConfig {
            soft_bytes_per_second: 0,
            hard_bytes_per_second: 1_000_000,
            burst_bytes: 4096,
            max_serialized_frame_bytes: 4096,
            policy: BytePolicy::ShedNormal,
        })));
        let drain_key = PlumtreePubSub::<RecordingTransport>::recovery_intent_key(
            topic, remote, "EAGER", b"drain",
        );
        assert!(pubsub
            .egress_limiter
            .try_reserve_data(drain_key, 3072, false)
            .is_ok());

        let frame = Bytes::from(vec![7; 1536]);
        let outcome = pubsub
            .send_to_peer_bounded_outcome(
                topic,
                remote,
                GossipStreamType::PubSub,
                frame.clone(),
                "IWANT",
                false,
            )
            .await
            .expect("bounded recovery send");
        assert!(matches!(outcome, PeerSendOutcome::Sent { .. }));
        assert_eq!(transport.send_count_to(remote), 1);
        assert_eq!(transport.sent_frames()[0].2, frame);
        let snapshot = pubsub.leaf_egress_snapshot();
        let purpose = snapshot
            .by_topic_and_purpose
            .iter()
            .find(|row| row.topic == topic.to_bytes() && row.purpose == "IWANT")
            .expect("IWANT accounting");
        assert_eq!(purpose.demanded_bytes, 1536);
        assert_eq!(purpose.charged_bytes, 1536);
        assert_eq!(purpose.sent_bytes, 1536);
        assert_eq!(purpose.send_failures, 0);
    }

    #[tokio::test]
    async fn test_iwant_graft() {
        let peer_id = test_peer_id(1);
        // RecordingTransport, not the real adapter: this test grafts a peer
        // with no live connection and asserts it STAYS grafted after the
        // IWANT repair send. Since x0x #380 a not-connected repair send
        // evicts the peer from the mesh (correctly — an unconnected peer is
        // not a mesh member), so the graft semantics are tested against a
        // transport where the send succeeds.
        let transport = RecordingTransport::new(peer_id);
        let pubsub = PlumtreePubSub::new(peer_id, transport, test_signing_key());
        let topic = TopicId::new([1u8; 32]);
        let from_peer = test_peer_id(2);

        // Initialize peer as lazy
        {
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics.entry(topic).or_insert_with(TopicState::new);
            state.lazy_peers.insert(from_peer);
        }

        // Publish a message to cache it
        let payload = Bytes::from("test");
        pubsub.publish(topic, payload.clone()).await.ok();

        // Get the actual cached msg_id (don't recalculate - epoch may have changed)
        let msg_id = {
            let topics = pubsub.topics.read_topic(&topic).await;
            let state = topics.get(&topic).unwrap();
            // Get the first (and only) cached message ID
            state
                .message_cache
                .peek_lru_message_id()
                .expect("message should be cached")
        };

        // Handle IWANT from lazy peer
        pubsub
            .handle_iwant(from_peer, topic, vec![msg_id])
            .await
            .ok();

        // Verify peer was grafted to eager
        let topics = pubsub.topics.read_topic(&topic).await;
        let state = topics.get(&topic).unwrap();
        assert!(state.eager_peers.contains(&from_peer));
        assert!(!state.lazy_peers.contains(&from_peer));
    }

    #[tokio::test]
    async fn test_iwant_graft_respects_max_eager_degree() {
        let peer_id = test_peer_id(1);
        // RecordingTransport for the same #380 reason as test_iwant_graft:
        // the degree cap is measured after a successful repair send.
        let transport = RecordingTransport::new(peer_id);
        let pubsub = PlumtreePubSub::new(peer_id, transport, test_signing_key());
        let topic = TopicId::new([10u8; 32]);
        let from_peer = test_peer_id(240);
        let mut connected = Vec::new();

        {
            let now = Instant::now();
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics.entry(topic).or_insert_with(TopicState::new);
            for i in 0..MAX_EAGER_DEGREE {
                let peer = test_peer_id(i as u8 + 30);
                connected.push(peer);
                state.eager_peers.insert(peer);
                let mut score = PeerScore::new_at(now);
                score.record_delivery();
                state.peer_scores.insert(peer, score);
            }
            state.lazy_peers.insert(from_peer);
        }

        let payload = Bytes::from("test");
        pubsub.publish(topic, payload).await.ok();
        let msg_id = {
            let topics = pubsub.topics.read_topic(&topic).await;
            let state = topics.get(&topic).unwrap();
            state
                .message_cache
                .peek_lru_message_id()
                .expect("message should be cached")
        };

        pubsub
            .handle_iwant(from_peer, topic, vec![msg_id])
            .await
            .ok();

        let topics = pubsub.topics.read_topic(&topic).await;
        let state = topics.get(&topic).unwrap();
        assert_eq!(
            state.eager_peers.len(),
            MAX_EAGER_DEGREE,
            "IWANT repair should not inflate EAGER above MAX_EAGER_DEGREE"
        );
    }

    #[tokio::test]
    async fn test_unknown_eager_sender_enters_lazy_when_mesh_is_full_enough() {
        let peer_id = test_peer_id(1);
        let transport = test_transport().await;
        let signing_key = test_signing_key();
        let pubsub = PlumtreePubSub::new(peer_id, transport, signing_key.clone());
        let topic = TopicId::new([11u8; 32]);
        let unknown_sender = test_peer_id(250);

        {
            let now = Instant::now();
            let mut topics = pubsub.topics.write_topic(&topic).await;
            let state = topics.entry(topic).or_insert_with(TopicState::new);
            for i in 0..MIN_EAGER_DEGREE {
                let peer = test_peer_id(i as u8 + 50);
                state.eager_peers.insert(peer);
                let mut score = PeerScore::new_at(now);
                score.record_delivery();
                state.peer_scores.insert(peer, score);
            }
        }

        let payload = Bytes::from("hello from an unknown sender");
        let msg_id = [99u8; 32];
        let header = MessageHeader {
            version: 1,
            payload_hash: None,
            topic,
            msg_id,
            kind: MessageKind::Eager,
            hop: 0,
            ttl: 10,
        };
        let header_bytes = postcard::to_stdvec(&header).expect("serialize");
        let signature = signing_key.sign(&header_bytes).expect("sign");
        let message = GossipMessage {
            header,
            payload: Some(payload),
            signature,
            public_key: signing_key.public_key().to_vec(),
        };

        pubsub
            .handle_eager(unknown_sender, topic, message)
            .await
            .expect("unknown sender eager should be accepted");

        let topics = pubsub.topics.read_topic(&topic).await;
        let state = topics.get(&topic).unwrap();
        assert_eq!(state.eager_peers.len(), MIN_EAGER_DEGREE);
        assert!(
            state.lazy_peers.contains(&unknown_sender),
            "unknown EAGER sender should not bypass LAZY-first admission"
        );
        assert!(!state.eager_peers.contains(&unknown_sender));
    }

