    #[test]
    fn test_payload_replay_detected() {
        let mut state = TopicState::new();
        let payload = b"hello world";

        assert!(
            !state.is_payload_replay(payload),
            "First insert should be new"
        );
        assert!(
            state.is_payload_replay(payload),
            "Second insert should be replay"
        );
    }

